B.dcl=s(["bspA = math.log(close[1])","bspB = math.log(f_sec(bspPair))","bspRa = ta.change(bspA)","bspRb = ta.change(bspB)","bspCorr = ta.correlation(bspRa, bspRb, bspLen)","bspSdA = ta.stdev(bspRa, bspLen)","bspSdB = ta.stdev(bspRb, bspLen)","bspBeta = bspSdB > 0 ? bspCorr * bspSdA / bspSdB : na","bspSpread = bspA - bspBeta * bspB","bspMa = ta.sma(bspSpread, bspLen)","bspSd = ta.stdev(bspSpread, bspLen)","score_betaspread = na(bspSd) ? 0.0 : bspSd > 0 ? math.max(math.min(-(bspSpread - bspMa) / bspSd / 2.0, 1.0), -1.0) : 0.0"],t.s)
B.b2x=new A.dC("betaspread","Beta-adjusted spread",B.cE,"score_betaspread",u.tS,B.cKq,B.dcl)
B.dqV=s(['rspBench = input.symbol("AMEX:SPY", "Benchmark", group = "Formula library")','rspLen = input.int(63, "Performance window (bars)", minval = 1, group = "Formula library")','rspRank = input.int(252, "Percentile window (bars)", minval = 1, group = "Formula library")'],t.s)
B.dpd=s(["rspRs = close[1] / f_sec(rspBench)","rspPr = ta.percentrank(ta.roc(rspRs, rspLen), rspRank)","score_rspct = na(rspPr) ? 0.0 : (rspPr - 50.0) / 50.0"],t.s)
B.b2q=new A.dC("rspct","Relative strength percentile",B.cE,"score_rspct",u.mh,B.dqV,B.dpd)
B.dzv=s(['rvLen = input.int(21, "Volatility window (bars)", minval = 2, group = "Formula library")','rvRef = input.float(20.0, "Reference annualized vol %", minval = 0.1, group = "Formula library")'],t.s)
B.cuo=s(["rvVol = ta.stdev(math.log(close / close[1]), rvLen) * math.sqrt(252) * 100.0","score_rvol = na(rvVol) ? na : math.max(math.min((rvRef - rvVol) / rvRef, 1.0), -1.0)"],t.s)
B.b2K=new A.dC("rvol","Realized volatility",B.en,"score_rvol",u.c8,B.dzv,B.cuo)
B.d9j=s(['pkvLen = input.int(21, "Volatility window (bars)", minval = 1, group = "Formula library")','pkvRef = input.float(20.0, "Reference annualized vol %", minval = 0.1, group = "Formula library")'],t.s)
B.dbl=s(["pkvHl = math.log(high / low)","pkvVol = math.sqrt(ta.sma(pkvHl * pkvHl, pkvLen) / (4.0 * math.log(2.0)) * 252.0) * 100.0","score_parkvol = na(pkvVol) ? na : math.max(math.min((pkvRef - pkvVol) / pkvRef, 1.0), -1.0)"],t.s)
B.b2C=new A.dC("parkvol","Parkinson volatility",B.en,"score_parkvol",u.a2,B.d9j,B.dbl)
B.dCo=s(['gkvLen = input.int(21, "Volatility window (bars)", minval = 1, group = "Formula library")','gkvRef = input.float(20.0, "Reference annualized vol %", minval = 0.1, group = "Formula library")'],t.s)
B.d5o=s(["gkvHl = math.log(high / low)","gkvCo = math.log(close / open)","gkvVar = ta.sma(0.5 * gkvHl * gkvHl - (2.0 * math.log(2.0) - 1.0) * gkvCo * gkvCo, gkvLen)","gkvVol = math.sqrt(gkvVar * 252.0) * 100.0","score_gkvol = na(gkvVol) ? na : math.max(math.min((gkvRef - gkvVol) / gkvRef, 1.0), -1.0)"],t.s)
B.b2u=new A.dC("gkvol","Garman-Klass volatility",B.en,"score_gkvol",u.c2,B.dCo,B.d5o)
B.dyE=s(['vrpVix = input.symbol("CBOE:VIX", "Implied volatility (VIX)", group = "Formula library")','vrpRef = input.symbol("AMEX:SPY", "Market for realized vol", group = "Formula library")','vrpLen = input.int(21, "Realized-vol window (bars)", minval = 2, group = "Formula library")','vrpSpan = input.float(5.0, "Premium for a full vote (vol points)", minval = 0.1, group = "Formula library")'],t.s)
B.cYF=s(["vrpPx = f_sec(vrpRef)","vrpRv = ta.stdev(math.log(vrpPx / vrpPx[1]), vrpLen) * math.sqrt(252) * 100.0","vrpGap = f_sec(vrpVix) - vrpRv","score_vrp = na(vrpGap) ? 0.0 : math.max(math.min(vrpGap / vrpSpan, 1.0), -1.0)"],t.s)
B.b2z=new A.dC("vrp","Volatility risk premium",B.cE,"score_vrp",u.sC,B.dyE,B.cYF)
B.cHP=s(['vovLen = input.int(21, "Volatility window (bars)", minval = 2, group = "Formula library")','vovWin = input.int(63, "Vol-of-vol window (bars)", minval = 2, group = "Formula library")','vovRef = input.float(0.25, "Reference vol of vol (ratio)", minval = 0.01, group = "Formula library")'],t.s)
B.dh2=s(["vovRv = ta.stdev(math.log(close / close[1]), vovLen)","vovMean = ta.sma(vovRv, vovWin)","vovSd = ta.stdev(vovRv, vovWin)","vovCv = vovMean > 0 ? vovSd / vovMean : na","score_volofvol = na(vovCv) ? na : math.max(math.min((vovRef - vovCv) / vovRef, 1.0), -1.0)"],t.s)
B.b2y=new A.dC("volofvol","Vol of vol",B.en,"score_volofvol",u.gv,B.cHP,B.dh2)
B.d5W=s(['atpLen = input.int(14, "ATR length (bars)", minval = 1, group = "Formula library")','atpRef = input.float(2.0, "Reference ATR % of price", minval = 0.01, group = "Formula library")'],t.s)
B.d1A=s(["atpTr = na(close[1]) ? high - low : math.max(high - low, math.max(math.abs(high - close[1]), math.abs(low - close[1])))","atpPct = 100.0 * ta.rma(atpTr, atpLen) / close","score_atrpct = na(atpPct) ? na : math.max(math.min((atpRef - atpPct) / atpRef, 1.0), -1.0)"],t.s)
B.b2t=new A.dC("atrpct","ATR percent",B.en,"score_atrpct",u.pc,B.d5W,B.d1A)
B.dxz=s(['vrgLen = input.int(21, "Volatility window (bars)", minval = 2, group = "Formula library")','vrgRank = input.int(252, "Percentile window (bars)", minval = 1, group = "Formula library")'],t.s)
B.cRg=s(["vrgRv = ta.stdev(math.log(close / close[1]), vrgLen)","vrgPr = ta.percentrank(vrgRv, vrgRank)","score_volregime = na(vrgPr) ? na : (50.0 - vrgPr) / 50.0"],t.s)
B.b2P=new A.dC("volregime","Vol regime percentile",B.en,"score_volregime",u.bw,B.dxz,B.cRg)
B.dfX=s(['ddpLen = input.int(252, "Peak look-back (bars)", minval = 1, group = "Formula library")','ddpMax = input.float(20.0, "Drawdown for a full negative vote (%)", minval = 0.1, group = "Formula library")'],t.s)
B.dcR=s(["ddpDd = 100.0 * (1.0 - close / ta.highest(close, ddpLen))","score_ddepth = na(ddpDd) ? na : math.max(math.min(1.0 - 2.0 * ddpDd / ddpMax, 1.0), -1.0)"],t.s)
B.b2r=new A.dC("ddepth","Drawdown depth",B.en,"score_ddepth",u.EA,B.dfX,B.dcR)
B.dBg=s(['dduLen = input.int(252, "Peak look-back (bars)", minval = 1, group = "Formula library")','dduMax = input.int(126, "Bars under water for a full negative vote", minval = 1, group = "Formula library")'],t.s)
B.dcH=s(["dduBars = ta.barssince(close >= ta.highest(close, dduLen))","score_dddur = na(dduBars) ? na : math.max(math.min(1.0 - 2.0 * dduBars / dduMax, 1.0), -1.0)"],t.s)
B.b2L=new A.dC("dddur","Drawdown duration",B.en,"score_dddur",u.qp,B.dBg,B.dcH)
B.d8_=s(['ulcLen = input.int(14, "Ulcer window (bars)", minval = 1, group = "Formula library")','ulcRef = input.float(5.0, "Reference Ulcer index", minval = 0.01, group = "Formula library")'],t.s)
B.doD=s(["ulcDd = 100.0 * (close / ta.highest(close, ulcLen) - 1.0)","ulcIdx = math.sqrt(ta.sma(ulcDd * ulcDd, ulcLen))","score_ulcer = na(ulcIdx) ? na : math.max(math.min((ulcRef - ulcIdx) / ulcRef, 1.0), -1.0)"],t.s)
B.b2M=new A.dC("ulcer","Ulcer index",B.en,"score_ulcer",u.yF,B.d8_,B.doD)
B.cn8=s(['rylFront = input.symbol("NYMEX:CL1!", "Front contract", group = "Formula library")','rylNext = input.symbol("NYMEX:CL2!", "Next contract", group = "Formula library")','rylSpan = input.float(10.0, "Annualized roll yield for a full vote (%)", minval = 0.1, group = "Formula library")'],t.s)
B.dat=s(["rylFr = f_sec(rylFront)","rylNx = f_sec(rylNext)","rylRoll = rylNx > 0 ? 1200.0 * (rylFr / rylNx - 1.0) : na","score_rollyield = na(rylRoll) ? 0.0 : math.max(math.min(rylRoll / rylSpan, 1.0), -1.0)"],t.s)
B.b2o=new A.dC("rollyield","Futures roll yield",B.cE,"score_rollyield",u.oh,B.cn8,B.dat)
B.d_m=s(['fxcHome = input.symbol("FRED:DGS10", "Home 10-year yield", group = "Formula library")','fxcForeign = input.symbol("FRED:IRLTLT01JPM156N", "Foreign 10-year yield", group = "Formula library")','fxcSpan = input.float(3.0, "Differential for a full vote (pct points)", minval = 0.1, group = "Formula library")'],t.s)
B.dpT=s(["fxcDiff = f_sec(fxcHome) - f_sec(fxcForeign)","score_fxcarry = na(fxcDiff) ? 0.0 : math.max(math.min(fxcDiff / fxcSpan, 1.0), -1.0)"],t.s)
B.b2J=new A.dC("fxcarry","FX carry proxy",B.cE,"score_fxcarry",u.uf,B.d_m,B.dpT)
B.d6I=s(['cvmSym = input.symbol("FRED:T10Y2Y", "10y minus 2y spread", group = "Formula library")','cvmLen = input.int(63, "Change window (bars)", minval = 1, group = "Formula library")','cvmSpan = input.float(0.5, "Change for a full vote (pct points)", minval = 0.01, group = "Formula library")'],t.s)
B.deh=s(["cvmChg = ta.change(f_sec(cvmSym), cvmLen)","score_curvemom = na(cvmChg) ? 0.0 : math.max(math.min(cvmChg / cvmSpan, 1.0), -1.0)"],t.s)
B.b2l=new A.dC("curvemom","Curve slope momentum",B.cE,"score_curvemom",u.ES,B.d6I,B.deh)
B.caC=s(['hstLen = input.int(100, "Hurst window (bars)", minval = 8, group = "Formula library")'],t.s)
B.dqo=s(["hstRet = math.log(close / close[1])","hstMean = ta.sma(hstRet, hstLen)","hstSd = ta.stdev(hstRet, hstLen)","hstDir = math.sign(ta.change(close, hstLen))","float hstH = na","if not na(hstMean) and hstSd > 0","    float hstY = 0.0","    float hstHi = 0.0","    float hstLo = 0.0","    for i = hstLen - 1 to 0","        hstY += hstRet[i] - hstMean","        hstHi := math.max(hstHi, hstY)","        hstLo := math.min(hstLo, hstY)","    hstH := math.log((hstHi - hstLo) / hstSd) / math.log(hstLen)","score_hurst = na(hstH) or na(hstDir) ? na : hstDir * math.max(math.min((hstH - math.log(1.2533) / math.log(hstLen) - 0.5) * 5.0, 1.0), 0.0)"],t.s)
B.b2F=new A.dC("hurst","Hurst exponent",B.en,"score_hurst",u.fj,B.caC,B.dqo)
B.dvC=s(['kerLen = input.int(21, "Efficiency window (bars)", minval = 1, group = "Formula library")'],t.s)
B.d80=s(["kerNet = ta.change(close, kerLen)","kerPath = ta.sma(math.abs(ta.change(close)), kerLen) * kerLen","score_kaufer = na(kerNet) or na(kerPath) ? na : kerPath > 0 ? math.max(math.min(kerNet / kerPath, 1.0), -1.0) : 0.0"],t.s)
B.b2N=new A.dC("kaufer","Kaufman efficiency",B.en,"score_kaufer",u.aa,B.dvC,B.d80)
B.ddq=s(['fipLen = input.int(252, "Window (bars)", minval = 2, group = "Formula library")'],t.s)
B.diX=s(["fipRet = ta.change(close)","fipUp = ta.sma(na(fipRet) ? na : fipRet > 0 ? 1.0 : 0.0, fipLen)","fipDn = ta.sma(na(fipRet) ? na : fipRet < 0 ? 1.0 : 0.0, fipLen)","fipDir = math.sign(ta.change(close, fipLen))","score_frogpan = na(fipUp) or na(fipDn) or na(fipDir) ? na : fipDir * (fipUp - fipDn)"],t.s)
B.b2R=new A.dC("frogpan","Frog in the pan",B.en,"score_frogpan",u.mO,B.ddq,B.diX)
B.dfn=s(['m121Long = input.int(252, "Look-back (bars)", minval = 2, group = "Formula library")','m121Skip = input.int(21, "Skip the latest (bars)", minval = 0, group = "Formula library")','m121Span = input.float(25.0, "Return for a full vote (%)", minval = 0.1, group = "Formula library")'],t.s)
B.dsh=s(["m121Ret = 100.0 * (close[m121Skip] / close[m121Long] - 1.0)","score_mom121 = na(m121Ret) ? na : math.max(math.min(m121Ret / m121Span, 1.0), -1.0)"],t.s)
B.b2s=new A.dC("mom121","12-1 momentum",B.en,"score_mom121",u.pw,B.dfn,B.dsh)
B.d1k=s(['crgBear = input.int(252, "Bear-market look-back (bars)", minval = 1, group = "Gates")','crgVolLen = input.int(21, "Volatility and rebound window (bars)", minval = 2, group = "Gates")','crgVolRank = input.float(80.0, "High-volatility percentile", minval = 0, maxval = 100, group = "Gates")'],t.s)
B.dtR=s(["crgPast = ta.roc(close, crgBear)","crgRv = ta.stdev(math.log(close / close[1]), crgVolLen)","crgPr = ta.percentrank(crgRv, 252)","crgUp = ta.roc(close, crgVolLen)","gate_crashgate = na(crgPast) or na(crgPr) or na(crgUp) ? 1.0 : crgPast < 0 and crgPr >= crgVolRank ? (crgUp > 0 ? 0.0 : 0.5) : 1.0"],t.s)
B.b2H=new A.dC("crashgate","Momentum crash gate",B.mw,"gate_crashgate",u.gj,B.d1k,B.dtR)
B.deG=s(['klyLen = input.int(252, "Kelly window (bars)", minval = 2, group = "Sizing")','klyFrac = input.float(0.5, "Kelly fraction (0.5 = half-Kelly)", minval = 0, maxval = 1, group = "Sizing")','klyMax = input.float(1.0, "Max position scalar", minval = 0, group = "Sizing")'],t.s)
B.dBE=s(["klyRet = close / close[1] - 1.0","klyP = ta.sma(na(klyRet) ? na : klyRet > 0 ? 1.0 : 0.0, klyLen)","klyUp = ta.sma(na(klyRet) ? na : math.max(klyRet, 0.0), klyLen)","klyDn = ta.sma(na(klyRet) ? na : math.max(-klyRet, 0.0), klyLen)","klyF = klyUp > 0 and klyDn > 0 ? klyP * (1.0 - klyP) * (1.0 / klyDn - 1.0 / klyUp) : na","posScalar = na(klyF) ? 1.0 : math.max(math.min(klyFrac * klyF, klyMax), 0.0)"],t.s)
B.b2m=new A.dC("kelly","Kelly fraction",B.kS,"posScalar",u.hy,B.deG,B.dBE)
B.ddx=s(['ivvA = input.symbol("NASDAQ:TLT", "Basket asset 1", group = "Sizing")','ivvB = input.symbol("AMEX:GLD", "Basket asset 2", group = "Sizing")','ivvLen = input.int(63, "Volatility window (bars)", minval = 2, group = "Sizing")','ivvMax = input.float(1.0, "Max position scalar", minval = 0, group = "Sizing")'],t.s)
B.d1b=s(["ivvC = close[1]","ivvPa = f_sec(ivvA)","ivvPb = f_sec(ivvB)","ivvV0 = ta.stdev(math.log(ivvC / ivvC[1]), ivvLen)","ivvVa = ta.stdev(math.log(ivvPa / ivvPa[1]), ivvLen)","ivvVb = ta.stdev(math.log(ivvPb / ivvPb[1]), ivvLen)","ivvW = ivvV0 > 0 and ivvVa > 0 and ivvVb > 0 ? (1.0 / ivvV0) / (1.0 / ivvV0 + 1.0 / ivvVa + 1.0 / ivvVb) : na","posScalar = na(ivvW) ? 1.0 : math.max(math.min(3.0 * ivvW, ivvMax), 0.0)"],t.s)
B.b2E=new A.dC("invvol","Inverse-vol weight",B.kS,"posScalar",u.o_,B.ddx,B.d1b)
B.dBr=s(['shpLen = input.int(252, "Sharpe window (bars)", minval = 2, group = "Formula library")','shpRef = input.float(2.0, "Sharpe for a full vote", minval = 0.1, group = "Formula library")'],t.s)
B.d7B=s(["shpRet = math.log(close / close[1])","shpMu = ta.sma(shpRet, shpLen)","shpSd = ta.stdev(shpRet, shpLen)","shpRatio = shpSd > 0 ? shpMu / shpSd * math.sqrt(252) : na","score_rsharpe = na(shpRatio) ? na : math.max(math.min(shpRatio / shpRef, 1.0), -1.0)"],t.s)
B.b2B=new A.dC("rsharpe","Rolling Sharpe",B.en,"score_rsharpe",u.j7,B.dBr,B.d7B)
B.d7D=s(['sorLen = input.int(252, "Sortino window (bars)", minval = 2, group = "Formula library")','sorRef = input.float(3.0, "Sortino for a full vote", minval = 0.1, group = "Formula library")'],t.s)
B.cYq=s(["sorRet = math.log(close / close[1])","sorMu = ta.sma(sorRet, sorLen)","sorNeg = na(sorRet) ? na : math.min(sorRet, 0.0)","sorDd = math.sqrt(ta.sma(sorNeg * sorNeg, sorLen))","score_rsortino = na(sorMu) or na(sorDd) ? na : sorDd > 0 ? math.max(math.min(sorMu / sorDd * math.sqrt(252) / sorRef, 1.0), -1.0) : sorMu > 0 ? 1.0 : 0.0"],t.s)
B.b2G=new A.dC("rsortino","Rolling Sortino",B.en,"score_rsortino",u.ed,B.d7D,B.cYq)
B.d_l=s(['calLen = input.int(252, "Calmar window (bars)", minval = 2, group = "Formula library")','calRef = input.float(2.0, "Calmar for a full vote", minval = 0.1, group = "Formula library")'],t.s)
B.dsZ=s(["calOk = not na(ta.sma(close, calLen + 1))","calAnn = math.pow(close / close[calLen], 252.0 / calLen) - 1.0","float calMdd = na","if calOk","    float calPk = close[calLen]","    float calDd = 0.0","    for i = calLen to 0","        calPk := math.max(calPk, close[i])","        calDd := math.max(calDd, 1.0 - close[i] / calPk)","    calMdd := calDd","score_rcalmar = na(calMdd) or na(calAnn) ? na : calMdd > 0 ? math.max(math.min(calAnn / calMdd / calRef, 1.0), -1.0) : calAnn > 0 ? 1.0 : 0.0"],t.s)
B.b2k=new A.dC("rcalmar","Rolling Calmar",B.en,"score_rcalmar",u.Bj,B.d_l,B.dsZ)
B.cZa=s(['maeLen = input.int(21, "Holding window (bars)", minval = 1, group = "Formula library")','maeRef = input.float(10.0, "Dip for a full negative vote (%)", minval = 0.1, group = "Formula library")'],t.s)
B.dsU=s(["maeDip = 100.0 * (ta.lowest(low, maeLen) / close[maeLen] - 1.0)","score_maeproxy = na(maeDip) ? na : math.max(math.min(1.0 + 2.0 * maeDip / maeRef, 1.0), -1.0)"],t.s)
B.b2v=new A.dC("maeproxy","Adverse excursion proxy",B.en,"score_maeproxy",u.oN,B.cZa,B.dsU)
B.d5n=s(['crrA = input.symbol("AMEX:SPY", "Basket asset 1", group = "Gates")','crrB = input.symbol("NASDAQ:TLT", "Basket asset 2", group = "Gates")','crrC = input.symbol("AMEX:GLD", "Basket asset 3", group = "Gates")','crrLen = input.int(63, "Correlation window (bars)", minval = 2, group = "Gates")','crrLo = input.float(0.3, "Average correlation that starts to cut", group = "Gates")','crrHi = input.float(0.6, "Average correlation that cuts to flat", group = "Gates")'],t.s)
B.dtc=s(["crrPa = f_sec(crrA)","crrPb = f_sec(crrB)","crrPc = f_sec(crrC)","crrRa = math.log(crrPa / crrPa[1])","crrRb = math.log(crrPb / crrPb[1])","crrRc = math.log(crrPc / crrPc[1])","crrAvg = (ta.correlation(crrRa, crrRb, crrLen) + ta.correlation(crrRa, crrRc, crrLen) + ta.correlation(crrRb, crrRc, crrLen)) / 3.0","gate_corrgate = na(crrAvg) ? 1.0 : math.max(math.min((crrHi - crrAvg) / math.max(crrHi - crrLo, 0.01), 1.0), 0.0)"],t.s)
B.b2Q=new A.dC("corrgate","Correlation regime gate",B.mw,"gate_corrgate",u.p8,B.d5n,B.dtc)
B.ddN=s([B.b2n,B.b2w,B.b2O,B.b2A,B.b2I,B.b2p,B.b2D,B.b2x,B.b2q,B.b2K,B.b2C,B.b2u,B.b2z,B.b2y,B.b2t,B.b2P,B.b2r,B.b2L,B.b2M,B.b2o,B.b2J,B.b2l,B.b2F,B.b2N,B.b2R,B.b2s,B.b2H,B.b2m,B.b2E,B.b2B,B.b2G,B.b2k,B.b2v,B.b2Q],t.gy)
B.aE7=s(["domenica","luned\xec","marted\xec","mercoled\xec","gioved\xec","venerd\xec","sabato"],t.s)
