B.f_s=new A.b(B.h,["{n} votes each score the chart symbol from \u22121 (bearish) to +1 (bullish) on every bar. Votes that need economic data read it inside TradingView; here they stay neutral.","\ud22c\ud45c {n}\uac1c\uac00 \ubd09\ub9c8\ub2e4 \ucc28\ud2b8 \uc885\ubaa9\uc5d0 \u22121(\uc57d\uc138)\uc5d0\uc11c +1(\uac15\uc138) \uc0ac\uc774 \uc810\uc218\ub97c \ub9e4\uaca8\uc694. \uacbd\uc81c \ub370\uc774\ud130\uac00 \ud544\uc694\ud55c \ud22c\ud45c\ub294 TradingView \uc548\uc5d0\uc11c \uc77d\uace0, \uc5ec\uae30\uc11c\ub294 \uc911\ub9bd\uc73c\ub85c \ub0a8\uc544\uc694."],t.w)
B.er6=new A.b(B.h,["{n} gates multiply the result by 0 to 1: they mute the signal in trendless chop or cut it to flat in a credit shock.","\uac8c\uc774\ud2b8 {n}\uac1c\uac00 \uacb0\uacfc\uc5d0 0~1\uc744 \uacf1\ud574\uc694. \ucd94\uc138 \uc5c6\ub294 \ud6a1\ubcf4\uc7a5\uc5d0\uc11c\ub294 \uc2e0\ud638\ub97c \uc904\uc774\uace0, \uc2e0\uc6a9 \ucda9\uaca9 \ub54c\ub294 0\uc73c\ub85c \ub9cc\ub4e4\uc5b4\uc694."],t.w)
B.eZE=new A.b(B.h,["The weighted average of the votes, times the gates, becomes the composite from \u2212100 to +100. Blended layers add their votes to this average at their own weights.","\ud22c\ud45c\uc758 \uac00\uc911 \ud3c9\uade0\uc5d0 \uac8c\uc774\ud2b8\ub97c \uacf1\ud55c \uac12\uc774 \u2212100~+100\uc758 \uc885\ud569 \uc810\uc218\uac00 \ub3fc\uc694. \ud569\uccd0\uc9c4 \ub808\uc774\uc5b4\ub294 \uc790\uae30 \uac00\uc911\uce58\ub85c \uc774 \ud3c9\uade0\uc5d0 \ud22c\ud45c\ub97c \ub354\ud574\uc694."],t.w)
