B.erh=new A.b(B.h,["Above the entry threshold it goes long; below 0 it goes flat. The gap between the two thresholds is the hysteresis that cuts whipsaw. Orders fill on the NEXT bar, after costs.","\uc9c4\uc785 \uae30\uc900\ubcf4\ub2e4 \ub192\uc73c\uba74 \ub9e4\uc218 \ubcf4\uc720, 0\ubcf4\ub2e4 \ub0ae\uc73c\uba74 \uad00\ub9dd\uc774\uc5d0\uc694. \ub450 \uae30\uc900 \uc0ac\uc774\uc758 \uac04\uaca9\uc774 \uc7a6\uc740 \ubc88\ubcf5\uc744 \uc904\uc774\ub294 \uc644\ucda9 \uad6c\uac04\uc774\uc5d0\uc694. \uc8fc\ubb38\uc740 \ube44\uc6a9\uc744 \ubc18\uc601\ud574 \ub2e4\uc74c \ubd09\uc5d0\uc11c \uccb4\uacb0\ub3fc\uc694."],t.w)
B.eES=new A.b(B.h,["Read the composite: above 0 the votes lean bullish, below 0 bearish. It is an indicator; switch to Strategy mode to backtest.","\uc885\ud569 \uc810\uc218\uac00 0\ubcf4\ub2e4 \ub192\uc73c\uba74 \ud22c\ud45c\uac00 \uac15\uc138 \ucabd, \ub0ae\uc73c\uba74 \uc57d\uc138 \ucabd\uc774\uc5d0\uc694. \uc9c0\ud45c\uc774\ubbc0\ub85c \uacfc\uac70 \ub370\uc774\ud130 \uc2dc\ud5d8\uc744 \ud558\ub824\uba74 \uc804\ub7b5 \ubaa8\ub4dc\ub85c \ubc14\uafb8\uc138\uc694."],t.w)
