B.emw=new A.b(B.h,["The Positioning cascade scenario: trend followers, dealers and short-vol sellers, with the 2018, 2020 and 2024 analogs.","2018\ub144, 2020\ub144, 2024\ub144 \uc720\uc0ac \uc0ac\ub840\uac00 \uc788\ub294 \ud3ec\uc9c0\uc158 \uc5f0\uc1c4 \ud558\ub77d \uc2dc\ub098\ub9ac\uc624\uc608\uc694. \ucd94\uc138 \ucd94\uc885\uc790, \ub51c\ub7ec, \ubcc0\ub3d9\uc131 \ub9e4\ub3c4\uc790\uac00 \ub098\uc640\uc694."],t.w)
B.exC=new A.b(B.h,["Use on SPY. Green markers = enough gauges calm to re-enter; red = the composite fell below 0. Check which data panels turned first: that is the stress's source.","SPY\uc5d0\uc11c \uc4f0\uc138\uc694. \ucd08\ub85d \ud45c\uc2dc\ub294 \uc7ac\uc9c4\uc785\ud560 \ub9cc\ud07c \ucda9\ubd84\ud55c \uc9c0\ud45c\uac00 \uc7a0\uc7a0\ud558\ub2e4\ub294 \ub73b\uc774\uace0, \ube68\uac04 \ud45c\uc2dc\ub294 \uc885\ud569 \uc810\uc218\uac00 0 \uc544\ub798\ub85c \ub0b4\ub824\uac14\ub2e4\ub294 \ub73b\uc774\uc5d0\uc694. \uc5b4\ub5a4 \ub370\uc774\ud130 \ud328\ub110\uc774 \uba3c\uc800 \ubc14\ub00c\uc5c8\ub294\uc9c0 \ubcf4\uc138\uc694. \uadf8\uac8c \uc2a4\ud2b8\ub808\uc2a4\uc758 \ucd9c\ucc98\uc608\uc694."],t.w)
B.ete=new A.b(B.h,["Slow-building stress such as 2007\u201308, when credit spreads and banks weakened months before the worst of the stock decline.","2007~08\ub144\ucc98\ub7fc \uc8fc\uac00 \ud558\ub77d\uc774 \uac00\uc7a5 \uc2ec\ud574\uc9c0\uae30 \uba87 \ub2ec \uc804\uc5d0 \uc2e0\uc6a9 \uc2a4\ud504\ub808\ub4dc\uc640 \uc740\ud589\uc774 \uc57d\ud574\uc9c4 \uc11c\uc11c\ud788 \uc313\uc774\ub294 \uc2a4\ud2b8\ub808\uc2a4\uc5d0\uc11c \uc798 \ub9de\uc544\uc694."],t.w)
B.eG9=new A.b(B.h,["Sudden shocks with no build-up (March 2020) and sharp V-shaped recoveries, where the exit-below-0 rule re-enters late.","2020\ub144 3\uc6d4\ucc98\ub7fc \ubbf8\ub9ac \uc313\uc778 \uc9d5\ud6c4\uac00 \uc5c6\ub294 \uac11\uc791\uc2a4\ub7ec\uc6b4 \ucda9\uaca9\uacfc, 0 \uc544\ub798 \uccad\uc0b0 \uaddc\uce59\uc774 \ub2a6\uac8c \uc7ac\uc9c4\uc785\ud558\ub294 \uae09\ud55c V\uc790 \ud68c\ubcf5\uc5d0\uc11c\ub294 \uc798 \ub9de\uc9c0 \uc54a\uc544\uc694."],t.w)
