B.eBj=new A.b(B.h,["One-year correlation of the chart with cyclicals\xf7defensives.","\ucc28\ud2b8\uc640 \uacbd\uae30\ubbfc\uac10\uc8fc\xf7\ubc29\uc5b4\uc8fc\uc758 1\ub144 \uc0c1\uad00\uad00\uacc4\uc608\uc694."],t.w)
B.erJ=new A.b(B.h,["Put a sector ETF on the chart. A positive composite while that sector's panel leads the others says phase and strength agree.","\uc5c5\uc885 ETF\ub97c \ucc28\ud2b8\uc5d0 \uc62c\ub9ac\uc138\uc694. \uc885\ud569 \uc810\uc218\uac00 \uc591\uc218\uc774\uace0 \uadf8 \uc5c5\uc885 \ud328\ub110\uc774 \ub2e4\ub978 \uc5c5\uc885\ubcf4\ub2e4 \uc55e\uc11c\uba74 \uad6d\uba74\uacfc \uac15\ub3c4\uac00 \uc77c\uce58\ud55c\ub2e4\ub294 \ub73b\uc774\uc5d0\uc694."],t.w)
