B.eEb=new A.b(B.h,["Use on QQQ or NDX. A rising correlation and beta to USD/JPY mean carry is driving the index; that is when the alarm matters most.","QQQ\ub098 NDX\uc5d0\uc11c \uc4f0\uc138\uc694. USD/JPY\uc640\uc758 \uc0c1\uad00\uad00\uacc4\uc640 \ubca0\ud0c0\uac00 \uc624\ub974\uba74 \uce90\ub9ac\uac00 \uc9c0\uc218\ub97c \uc6c0\uc9c1\uc774\uace0 \uc788\ub2e4\ub294 \ub73b\uc774\uace0, \uadf8\ub54c \uacbd\ubcf4\uac00 \uac00\uc7a5 \uc911\uc694\ud574\uc694."],t.w)
