B.b4c=new A.D("groupOrder",B.W,"Ordering of group sections (List).",B.l,null,!1)
B.hLg=new A.D("dateColumns",B.kV,"Date columns for time buckets.",B.l,null,!1)
B.hE6=new A.D("subtitleColumns",B.kV,"Columns shown as subtitle.",B.l,null,!1)
