B.hdf=new A.dp("priolanes",'A three-lane prioritization view over a table\'s status column: Now (active), Pending (queued), Future (discussed). `done` rows and `excludeTypes` rows are hidden \u2014 a forward-looking view, not a full log. Optional project grouping walks CONTAINS edges (same generic edgesTable/edgeFrom/edgeTo/edgeType/containsType idiom as `explorer`/`entrythread`) up to the nearest ancestor whose type equals `projectType`. Drag a card between lanes (wide) or use its \u22ee "Move to\u2026" menu (any width) to rewrite its status through the normal write path.',B.caw,!1)
B.IH=new A.D("viewFilter",B.Q,"Opt-in (notesfilter-1123): the name of an app-level view filter (`ui.app.viewFilters.<name>`); rows are read through it, so every view naming it shows the same filtered set.",B.l,null,!1)
