B.i4d=new A.D("hideDefaultComposeChips",B.a8,'dispshared-1125: the composer "as <author>" and "to: <recipient>" chips are bare icons while at their default (the picker stays). Default false.',B.l,null,!1)
B.i0u=new A.D("authorPicker",B.a8,'Opt-in: the composer shows an "as <name> \u25be" chip to attribute the next entry to any authorTable row (the user\u2194collaborator turn). The choice is sticky and always resolves to a real row.',B.l,null,!1)
B.hEJ=new A.D("defaultAuthor",B.Q,'Row id (or a value token \u2014 `$setting:<key>` etc., resolved via the shared resolveValueToken) used as the author when the signed-in user is not itself an authorTable row (else the first authorFilter-matching row). Keeps the "by <name>" line from ever rendering blank.',B.l,null,!1)
B.hQU=new A.D("authorFilter",B.W,'Static { column, value|in } narrowing which authorTable rows can be attributed: the "as \u25be" picker only offers matching rows, and the first-row fallback only draws from them. When configured with NO matching rows, attribution resolves to EMPTY (renders the unattributed state) rather than any arbitrary row. Omitted (default): every authorTable row is eligible, exact prior behavior.',B.l,null,!1)
B.i3Q=new A.D("promptingColumn",B.L,"Ref column that records WHO a composed entry is directed at (the turn-taking recipient); written as a one-element list.",B.l,null,!1)
B.i_o=new A.D("promptingPicker",B.a8,'Opt-in: the composer shows a "to: <name> \u25be" chip to address the next entry to a recipient from authorTable ("Anyone" = no target).',B.l,null,!1)
B.i5d=new A.D("awaitingColumn",B.L,"Boolean column set true when a composed entry is directed at someone \u2014 opens the turn so the recipient sees it as pending until answered.",B.l,null,!1)
B.i4L=new A.D("editedByColumn",B.L,"Opt-in: editing a comment/title INLINE stamps this ref column with the current user (+ editedAtColumn=today) \u2014 the inline counterpart of the record editor's edit stamping.",B.l,null,!1)
B.hLf=new A.D("editedAtColumn",B.L,"Opt-in: date column stamped today on an inline edit (pairs with editedByColumn).",B.l,null,!1)
B.i6s=new A.D("parentEditedAtColumn",B.L,'Opt-in: posting a new entry (Add entry / attach / reply) stamps this date column on the THREAD\'S OWN node (nodeId, a row of `table`) with now \u2014 activity counts as an edit, so a task with fresh discussion but no direct field edit still surfaces in "edited recently" filters/sort. No-op unless declared (backward compatible).',B.l,null,!1)
B.hS6=new A.D("attachInline",B.a8,"Show + add attachments right on each card (thumbnails for images, chips for files, an Attach button in editable mode).",B.l,null,!1)
