B.i3E=new A.D("collapsible",B.a8,'Graph/dag (needs parentColumn): a node with nested children shows a collapse/expand toggle; collapsing hides its whole contained subtree and shows a "+N" badge (N = hidden descendants). Session-only, not persisted.',B.l,null,!1)
