B.hST=new A.D("artboard",B.W,"artboard-r1-1012. Optional `{width, height, label?}`: the region at the scene origin the drawing is FOR (e.g. a phone frame), drawn as an outlined sheet behind the content and used as the first-load fit target. Absent = no sheet.",B.l,null,!1)
B.hQN=new A.D("fidelity",B.bG,'How nodes RENDER (free layout): "auto" (default tinted card), "wireframe" (mono outline + white fill), or "themed" (each `kind` drawn as a real component \u2014 button/input/list/nav/image/text/section/frame).',B.a5w,null,!1)
B.hOL=new A.D("confirmDelete",B.a8,'Ask to confirm before deleting a node (also honors the app-wide "confirm before deleting" setting).',B.l,null,!1)
B.hKY=new A.D("pageTable",B.b4,'RENAME: table holding the current PAGE row. Set with pageId to show a tappable "rename page" chip on the canvas (for solo/embedded views).',B.l,null,!1)
