B.hX3=new A.D("linesFilterProperty",B.Q,"GeoJSON feature property (on linesAsset) matched against the CURRENT featureFilterColumn/featureFilterTable selection: only features whose property equals the selected value draw (nothing draws while unselected). Unset draws every line in the asset always, regardless of any selection \u2014 use this for an always-on network layer and set it for a per-selection route tree.",B.l,null,!1)
