B.hRL=new A.D("column",B.L,'Column holding the Markdown text (default "body"). The cell is read on EVERY build, so a host that rewrites the content under a stable row id (a single scratch row reused per article) always re-renders \u2014 this node keeps no copy that could go stale.',B.l,null,!1)
B.i3J=new A.D("titleColumn",B.L,"Optional column rendered as the page title above the text.",B.l,null,!1)
