B.hG3=new A.D("onLinkTap",B.W,'Action spec { fn, args } fired when a Markdown `[label](target)` link is tapped; `"$value"` in args is replaced by the raw link target, unmodified \u2014 the same contract `notepad`\'s `onLinkTap` uses. Unset \u2192 links render styled but inert.',B.l,null,!1)
B.hM4=new A.D("jumpToSectionSetting",B.Q,'Board-settings key whose value `"<nonce>::<heading text>"` scrolls to the first matching `#`/`##`/`###` heading (trimmed, case-insensitive). The leading nonce lets a repeated tap on the same section re-trigger. The landing position is an ESTIMATE \u2014 "near this section", not frame-perfect.',B.l,null,!1)
B.hGQ=new A.D("findEnabledSetting",B.Q,'Opt-in "Find in article" \u2014 restores the same feature `notepad`\'s `findEnabledSetting` offers, dropped when this applet migrated from `notepad` to `bookreader`. Names a board-settings key an external affordance (e.g. a summoned action-footer\'s find icon) toggles true/false to open/close an inline search bar docked above the page. The typed query, per-occurrence match highlighting, match-count feedback ("N of M"), next/prev stepping and scroll-to-match are all self-contained in this widget \u2014 no other prop or host wiring is needed. Unset (default) \u2192 zero footprint, byte-identical to before this prop existed.',B.l,null,!1)
B.hRV=new A.D("dropCaps",B.a8,"Drop capital on the first prose paragraph (default true). A paragraph that does not open with a LETTER renders normally instead.",B.l,null,!1)
B.i2_=new A.D("sectionRules",B.a8,"Thin centred ink rule above each `##` section (default true).",B.l,null,!1)
B.i6z=new A.D("justify",B.a8,"Justify body paragraphs (default false \u2014 ragged right, which reads better at narrow measures).",B.l,null,!1)
B.hZF=new A.D("accent",B.Q,"Link + drop-cap colour as `#rgb`/`#rrggbb`/`#aarrggbb`. Default is the palette oxblood (lifted for legibility in the night treatment). An unparseable value is ignored.",B.l,null,!1)
B.i4W=new A.D("paper",B.Q,"Page ground colour override (hex).",B.l,null,!1)
B.hLA=new A.D("ink",B.Q,"Body text colour override (hex).",B.l,null,!1)
B.hXi=new A.D("displayFont",B.Q,'Family for titles and headings (default "IM Fell English"; falls back to Lora/Georgia/serif when the app does not bundle it).',B.l,null,!1)
B.hND=new A.D("bodyFont",B.Q,'Family for body text (default "Lora", falling back to Georgia/serif).',B.l,null,!1)
B.i02=new A.D("maxWidth",B.aS,"Page measure in logical pixels (default 680) \u2014 the text column is centred and never wider than this.",B.l,null,!1)
B.hMI=new A.D("footer",B.Q,"Provenance / footer line under a closing rule (e.g. a source attribution). Empty \u2192 no footer.",B.l,null,!0)
B.hEb=new A.D("footerColumn",B.L,"Column on the bound row supplying the footer line; a non-empty value here wins over `footer`.",B.l,null,!1)
B.hMu=new A.D("imagesTable",B.b4,"Opt-in local image bytes: table holding base64 payloads a whole-line `![alt](local:<id>)` resolves against. Unset (default) \u2192 every image renders as its ALT TEXT. This node NEVER fetches an image: an http(s) src always renders alt text.",B.l,null,!1)
B.hQO=new A.D("imageSrcColumn",B.L,'Column on `imagesTable` holding the base64 payload (default "b64").',B.l,null,!1)
B.hXX=new A.D("scopedSubscription",B.a8,"Opt-in perf: only rebuild (re-parse the Markdown) when `table` or `imagesTable` actually changes, instead of on every board-wide notify (e.g. unrelated crawl/bookkeeping writes elsewhere on the board). Same mechanism `notepad`/`cards`/`table`/`dataview`/`explorer` use. Off by default: zero behavior change.",B.l,null,!1)
B.hFx=new A.D("tapChrome",B.a8,'A tap on the page body (never a link tap, never a scroll/drag) toggles `chromeSetting` true/false \u2014 mirrors mobile-browser chrome, hidden by default. Bind a sibling action footer\'s `showIf` to the same key (`{ setting: chromeSetting, equals: "true" }`) to show it only while chrome is toggled on. Off by default (false).',B.l,null,!1)
B.hZN=new A.D("chromeSetting",B.Q,'Board-settings key `tapChrome` flips between "true"/"false". Unset \u2192 derived from `table` (`"bookreaderChrome:<table>"`) so two bookreaders bound to different tables never collide.',B.l,null,!1)
B.i43=new A.D("fastScroll",B.a8,"Wikipedia-app-style right-edge fast-scroll: a draggable scrollbar thumb hugging the reading column's right edge, shown while the article scrolls and faded after ~1.5s idle. Dragging scrubs the whole document proportionally and floats a themed bubble naming the current section heading beside the thumb. Off by default (false): zero footprint for every existing bookreader use.",B.l,null,!1)
