B.hF_=new A.D("setting",B.Q,'Board-setting KEY the live value is written to via the same setSetting semantics every control uses (not durable unless allow-listed) \u2014 other nodes read it back live via "$setting:<key>".',B.l,null,!1)
B.hY8=new A.D("action",B.W,'Action spec { fn, args } fired on change; any literal "$value" in args (nested lists/maps included) is substituted with the current number first \u2014 e.g. drives mapSetFilter/mapSetPaint directly with zero extra plumbing.',B.l,null,!1)
B.i_3=new A.D("play",B.a8,"Opt-in auto-play/timelapse (default off): shows a play/pause button beside the slider that sweeps the value from the active range's start to its end, advancing by `step` (or 1/100th of the span when step is 0/omitted) every `playIntervalMs`, firing the SAME setting-write / action a manual change fires at every step. Pressing play restarts from the active-range start when the thumb is already at the end, otherwise continues from the current value. Any manual drag pauses playback in place (the `databars` play convention).",B.l,null,!1)
B.b4D=new A.D("playIntervalMs",B.aS,"Milliseconds between auto-play steps \u2014 default ~1200. Only used with play:true.",B.l,null,!1)
B.hKg=new A.D("playLoop",B.a8,"Whether auto-play wraps to the active-range start after reaching the end \u2014 default false (stops and flips the button back to play). Only used with play:true.",B.l,null,!1)
B.doj=s([B.i_e,B.hKm,B.i2Q,B.i6u,B.hR3,B.hZU,B.hX2,B.hF_,B.hY8,B.i_3,B.b4D,B.hKg],t.G)
B.hdQ=new A.dp("slider",'A minimal, single-value horizontal slider (min/max/step/value from JSON) \u2014 distinct from `datarange` (a dual-thumb column filter): this is a general-purpose control whose live value can write a named board SETTING (`setting`, readable elsewhere via the existing "$setting:<key>" token) and/or fire an arbitrary `action` (any literal "$value" in the action\'s args, however deeply nested, is substituted with the current number before firing) \u2014 e.g. driving `mapSetFilter`/`mapSetPaint` directly to threshold a map choropleth by a live budget value. Either, both, or neither may be set; debounced ~80ms while dragging, always flushed once on release. Opt into `play` for an auto-advance timelapse; a `sliderSetRange` action can constrain the slider to an active sub-range at runtime \u2014 see those props.',B.doj,!1)
B.dtN=s(["number","time","date"],t.s)
B.i0W=new A.D("mode",B.bG,"number (default) | time | date.",B.dtN,null,!1)
B.hRx=new A.D("min",B.aS,"number mode: minimum (default 0).",B.l,null,!1)
B.hE8=new A.D("max",B.aS,"number mode: maximum (default 100).",B.l,null,!1)
B.i0T=new A.D("step",B.aS,"number mode: step, may be fractional (default 1).",B.l,null,!1)
B.hVq=new A.D("decimals",B.aS,"number mode: digits after the point (default: from step).",B.l,null,!1)
B.i3H=new A.D("unit",B.Q,"number mode: suffix shown beside the wheel.",B.l,null,!1)
B.hOz=new A.D("minuteStep",B.aS,"time mode: minute increment (default 1).",B.l,null,!1)
B.hSV=new A.D("firstDate",B.Q,"date mode: earliest date, ISO yyyy-MM-dd (default 100 years back).",B.l,null,!1)
B.hK7=new A.D("lastDate",B.Q,"date mode: latest date, ISO yyyy-MM-dd (default 100 years ahead).",B.l,null,!1)
B.hYK=new A.D("value",B.Q,'Initial value when the setting is unset (number, "HH:mm" or ISO date).',B.l,null,!1)
B.hL8=new A.D("defaultValue",B.Q,"Fallback initial value when value is unset.",B.l,null,!1)
B.hZq=new A.D("label",B.Q,"Label above the wheel; may be a {lang: text} map.",B.l,null,!1)
B.hXk=new A.D("setting",B.Q,'Board-setting KEY the value is written to (same setSetting semantics as slider; read back via "$setting:<key>").',B.l,null,!1)
