B.hdb=new A.dp("wheel",'A scroll selector (wheel columns) for a number, a time of day or a date, bound to a board SETTING like `slider`. `mode` picks the shape: number (min/max/step/decimals/unit; fractional steps are exact), time (stored as "HH:mm"; 12h/24h follows the device) or date (stored as ISO "yyyy-MM-dd"). The wheel is a visible boxed field; drag, mouse wheel, keys and tap-to-type all work.',B.d2R,!1)
B.hHS=new A.D("hint",B.Q,"Placeholder shown when the field is empty; may be a {lang: text} map.",B.l,null,!0)
B.hT7=new A.D("debounceMs",B.aS,"Debounce window in ms for the change-fired action (default 350). Submit always fires immediately, uncoupled from this.",B.l,null,!1)
B.i5S=new A.D("action",B.W,'Action spec { fn, args } fired on debounced change and on submit; any literal "$value" in args (nested lists/maps included) is substituted with the field\'s current text first.',B.l,null,!1)
B.i_l=new A.D("focusSignal",B.W,'{table, id, column} \u2014 a value the host BUMPS to command external keyboard focus (e.g. a magnifier "start searching" toggle). Watched every rebuild; any change from the previously seen value requests focus. Optional.',B.l,null,!1)
B.hH6=new A.D("resetSignal",B.W,"{table, id, column} \u2014 same shape as focusSignal, but a change clears the field's own visible text and fires its `action` with an empty string, so bound downstream state clears too. Optional; distinct from focusSignal so one external toggle can choose either behavior per host-side state.",B.l,null,!1)
B.i0B=new A.D("contentPadding",B.W,"{left, top, right, bottom} in px, each optional (default 12 per side \u2014 the ordinary decoration inset). Lets the field's own text inset be pulled in line with unrelated sibling content sharing its row (e.g. list-row titles below it that start flush at the row's own screen inset, with no further indent of their own).",B.l,null,!1)
B.doP=s([B.hHS,B.hT7,B.i5S,B.i_l,B.hH6,B.i0B],t.G)
B.hcu=new A.dp("textinput",'A single-line free-text field \u2014 the `slider` $value-substitution pattern generalized from numeric to text. On every change (debounced) AND on submit (immediate) it can fire an `action` (any literal "$value" in args, however deeply nested, is substituted with the field\'s current text first \u2014 an empty field still fires, so a "clear" is expressible). No table binding of its own; drives whatever action the applet author wires (e.g. a debounced search-as-you-type `http` fetch).',B.doP,!1)
B.hM1=new A.D("table",B.b4,"Dataset the chips filter.",B.l,null,!1)
B.hQ2=new A.D("column",B.L,"Low-cardinality column.",B.l,null,!1)
