B.hOp=new A.D("max",B.aS,"Hide when distinct values exceed this (default 8).",B.l,null,!1)
B.hYn=new A.D("valueLabels",B.W,"Opt-in raw-value \u2192 display map for the chip TEXT: {raw: text-or-{lang:text}} (or column-keyed {column: {raw: ...}}), resolved against the ambient locale; unmapped values render raw (passthrough, never blank). The published filter value stays the RAW stored value.",B.l,null,!1)
B.hRF=new A.D("options",B.W,"Fixed List of values to offer INSTEAD of deriving the chip set from the data \u2014 use when the contract fixes the value set (e.g. a range enum) and the data may not yet carry a row for every value (a fresh snapshot with no activity yet for one value must still offer its chip). Skips the derive-from-data pass and the too-few/too-many auto-hide rule. Unset (default) keeps the original derive-from-data behavior, byte-identical.",B.l,null,!1)
B.hNe=new A.D("default",B.Q,'Value to select the FIRST time this control is shown for its (table, column) pair \u2014 i.e. while no filter has ever been set. Applied once; a user later toggling every chip off means "no constraint" exactly as before, it never re-snaps to this default. Unset (default) keeps the original empty-selection start, byte-identical.',B.l,null,!1)
B.d_j=s([B.hM1,B.hQ2,B.i40,B.hOp,B.hYn,B.hRF,B.hNe],t.G)
B.hde=new A.dp("datasegment","CONTROL block: one-tap VALUE CHIPS for a low-cardinality column (scenario/status switch). Multi-select; each tap toggles that value in the shared choice filter; none selected = no constraint. Hides itself when the column is not segment-shaped.",B.d_j,!1)
B.i6M=new A.D("table",B.b4,"Dataset the bars bucket.",B.l,null,!1)
B.hXj=new A.D("column",B.L,"Column whose distinct values become bars.",B.l,null,!1)
