B.i2D=new A.D("starterProjects",B.W,'Icon mode: ready-made projects offered under "Start from\u2026" \u2014 a list of {id, label, asset | rows}. Picking one ADDS its rows (fresh ids, parentId remapped; existing rows are never touched). asset = a bundled JSON file {"rows": [...]}.',B.l,"Starter projects",!1)
