B.hIq=new A.D("autoSelectFirst",B.a8,"Select the first row automatically once rows load (pairs with startBlank for an open-something-immediately explorer).",B.l,null,!1)
B.hPQ=new A.D("scopeTargets",B.W,"Restrict the explorer to these subtree root ids (scope the directory to a branch instead of the whole table).",B.l,null,!1)
B.hWS=new A.D("nestedScopeTargets",B.W,'A SECOND level of `scopeTargets`-shaped nesting for a `scopeTargets` entry whose own child rows are never a second `explorer` screen \u2014 a JSON object keyed by one of `scopeTargets`\' own tables, each value the SAME `[{table, column}]` list shape as `scopeTargets` itself, e.g. `{"screens": [{"table":"widgets","column":"screen"}, {"table":"pins","column":"screen"}]}`. The normal case (docs/notes/ bublie) needs nothing here: a `scopeTargets` child that IS its own `explorer` screen already gets this discovered for free by walking that screen\'s own `scopeTargets`/`scopeColumn`. This key exists for a scope-target whose children live inside one custom canvas node instead (composer: a board\'s `screens` row owns `widgets`/`pins`/ `frameImages` rows entirely inside the `compose` node, never a second Explorer) \u2014 the host\'s library-shape discovery (e.g. isan\'s `discoverLibraryShape`) reads this key explicitly so file export/ import can still capture those rows. Purely additive/opt-in \u2014 absent for every explorer that predates this key.',B.l,null,!1)
B.i0y=new A.D("scopeColumn",B.L,"Second-level nesting: further filter this explorer's own rail to rows whose value in this column matches the board's ACTIVE [setScope] value for (table, scopeColumn) \u2014 the scope an ANCESTOR explorer wrote via its own scopeTargets (e.g. Files > Boards).",B.l,null,!1)
B.djo=s(["drawer","collapsible","none","tabs"],t.s)
B.hF3=new A.D("railMode",B.bG,'How the file tree shows. "drawer" hides it behind a hamburger that slides it in as an overlay; "collapsible" shows the rail with a chevron that hides it (explorer.dart); "none" renders only the detail; "tabs" shows the leaves as a horizontal TAB STRIP above (default) or below the detail \u2014 worksheet tabs \u2014 placed by tabsSetting / tabsPosition (sheettabs-1107); default is a fixed side rail.',B.djo,null,!1)
B.i0D=new A.D("tabsSetting",B.Q,'railMode "tabs" only: board-setting KEY whose live value places the strip \u2014 "top" | "bottom" | "side" (side = the classic side rail; falls back to top at phone width). Unset/unknown values use tabsPosition. Durable only when the app allow-lists the key (durableSettings).',B.l,null,!1)
B.dz1=s(["top","bottom","side"],t.s)
B.hHa=new A.D("tabsPosition",B.bG,'railMode "tabs" only: where the strip sits when tabsSetting is unset (default "top").',B.dz1,null,!1)
B.i6F=new A.D("tabsHiddenColumn",B.L,'railMode "tabs" only: a boolean column; rows where it is true (hidden worksheets) are left out of the strip.',B.l,null,!1)
B.hLV=new A.D("tabsInTitleBar",B.a8,"railMode \"tabs\" only: on a wide window (720 px and up) the worksheet tabs render inside the host app's title bar, right after the title, and the page keeps no tab row; narrow windows, a bottom strip, or a host without a title bar keep the strip's own row (sheettabsbar-1124).",B.l,null,!1)
B.hYH=new A.D("startBlank",B.a8,'With nothing selected, render the detail child unbound + blank (e.g. a fresh draw canvas) instead of a "select a file" placeholder.',B.l,null,!1)
B.hKp=new A.D("emptyHome",B.a8,'With nothing selected, render a landing Home (new-file actions + recent files) instead of the "select a file" placeholder. Opening and creating are both optional \u2014 nothing auto-opens or auto-creates. startBlank takes precedence when both are set.',B.l,"Show a Home when nothing is open",!1)
B.djf=s(["default","tools"],t.s)
B.i1s=new A.D("homeLayout",B.bG,'Home layout. "tools" = large tool tiles (one per addItems kind: the kind icon from the shared kind table, the verb label and the entry\'s optional `hint`), Recent (last 8 files) below, "Start from an example\u2026" when examples exist, and a compact "New" button atop the tree opening the same tiles as a full-view popup. "default" (or unset) = the classic Home, unchanged.',B.djf,null,!1)
B.hMR=new A.D("homeTitle",B.Q,"Home heading; defaults to the rail title. May be a {lang: text} map.",B.l,null,!0)
B.hO6=new A.D("homeSubtitle",B.Q,"Muted line under the Home heading; omitted when unset. May be a {lang: text} map.",B.l,null,!0)
B.hJQ=new A.D("recencyColumn",B.L,"Sort column for the Home's Recent list (newest first); defaults to orderColumn.",B.l,null,!1)
B.i60=new A.D("completedByColumn",B.L,"Opt-in: ref column stamped with the actor when a row's status is set to doneStatus (cleared when it moves off done).",B.l,null,!1)
B.hGH=new A.D("finishedAtColumn",B.L,"Opt-in: date column stamped with today when status becomes doneStatus (cleared when it moves off done \u2014 an empty finish date is a fact).",B.l,null,!1)
B.i_0=new A.D("doneStatus",B.Q,'The statusColumn value that counts as "done" for completion stamping (default "done").',B.l,null,!1)
B.hWM=new A.D("defaultActor",B.Q,"Row id used as the completer when the signed-in user is not a row of the completedBy ref's table (else the first row).",B.l,null,!1)
B.hPw=new A.D("fileIconByKind",B.a8,"Resolve each leaf's icon from its own kindColumn value (a distinct glyph per row) instead of one shared fileIcon.",B.l,null,!1)
B.hTt=new A.D("tools",B.W,'Tool registry (suitetools-1122): ONE ordered list of creatable kinds [{id, kind, label, hint?, name?, icon?, embed:{appletId, screen} | detail:{node}, pages?: true|false|{overrides}}]. Replaces addItems AND the hand-written detail switch: the tools-Home tiles, the New popup/menu, the per-kind detail switch and the tile + tree-row glyph (icon via the engine kind table) all derive from it. With tools, `detail` is the fallback for a kind no tool claims. `pages` true (default) wraps the editor in `toolPages`; false = bare editor (picture tools). An embed must pin a non-explorer screen. A placeholder {id, label, hint?, icon?, comingSoon: true} draws a greyed "coming later" tile only (no New entry, no file, no detail case); placeholders sort after the real tools.',B.l,null,!1)
B.hQ9=new A.D("toolPages",B.W,'With `tools`: the `pages` wrapper template a tool with pages:true opens in (table/nameColumn/parentColumn/kindColumn default from the explorer; pageValue "page"; stripOnlyWhenExtra true).',B.l,null,!1)
B.hJt=new A.D("addItems",B.W,'Extra typed "New <x>" actions beyond New file: [{label, icon, values, hint}] \u2014 `hint` is the tools-Home tile\'s one-line description; with fileIconByKind an entry that stamps a kind draws that kind\'s glyph from the shared kind table (its own `icon` is then not needed) \u2014 each stamps values on the new leaf (e.g. {kind:"doc"}); shown as one "New" menu. An entry may instead give {label, icon, action:{fn,args}} (e.g. Mokup\'s "New from template", firing instantiateTemplate) \u2014 the action fires directly and no leaf is created here, for an action that mints its own root row. `action` wins over `values` if an entry has both.',B.l,null,!1)
B.hHP=new A.D("edgesTable",B.b4,"Opt-in GRAPH/edges-mode: relations table (rows {from,to,type}) that resolves parent\u2192child instead of the single parentColumn \u2014 a node can have MANY parents (many-to-many) and shows under each. Null (default) = classic single-parent tree.",B.l,null,!1)
B.i07=new A.D("edgeFrom",B.L,'Edges-mode: source-id column on edgesTable (default "from").',B.l,null,!1)
B.i4b=new A.D("edgeTo",B.L,'Edges-mode: target-id column on edgesTable (default "to").',B.l,null,!1)
B.hHu=new A.D("edgeType",B.L,'Edges-mode: edge-kind column on edgesTable (default "type").',B.l,null,!1)
B.hW1=new A.D("containsType",B.Q,'Edges-mode: edgeType value meaning "contains" (default "contains").',B.l,null,!1)
B.hSJ=new A.D("sharedBadge",B.a8,'Edges-mode: show a small "also in N" chip on a node with more than one incoming contains-edge (lives under several parents).',B.l,null,!1)
B.hGS=new A.D("inboxColumn",B.L,'ideasgraft-1026 (classic parentColumn mode): opt-in capture INBOX \u2014 a boolean column. A new TOP-LEVEL leaf is stamped true and lists in an "Inbox \xb7 N" section above the tree (and on the phone landing) instead of in it; the row menu and the open row\'s filing strip gain "File into\u2026" \u2014 a full-view picker of ONE home (or the top level) that sets parentColumn and clears the flag. Cycle-guarded.',B.l,null,!1)
B.hIK=new A.D("schedule",B.W,'ideastime-1027: opt-in SCHEDULE strip under the open row: {dateColumn, timeColumn?, kindColumn?, doneColumn?, noneValue?, kinds: [{value, label, color?, done?}]}. Shows "Schedule\u2026" when the row has no date/kind, else kind \xb7 date \xb7 time; tapping opens a full popup to set or remove the schedule (one undo step).',B.l,null,!1)
B.hFL=new A.D("place",B.W,'ideasgeo-1027: opt-in PLACE strip under the schedule strip: {whereColumn, nameColumn?}. Shows "Set place\u2026" when the row has no pin/name, else the place name (or coordinates); tapping opens a full popup with a name field and the map-pin picker (Save/Remove write both columns in one undo step). whereColumn holds "lat, lng".',B.l,null,!1)
B.hQh=new A.D("pageTools",B.W,'pagetools-m1-1031: declare engine PAGE TOOLS for this table instead of hand-wiring them: {tools: ["schedule", "place"], <tool>: {overrides}}. Each tool resolves to its registry defaults (page_tools.dart: schedule = when/whenTime/scheduleKind/done + to-do/appointment/event kinds; place = where/place) with per-tool overrides merged over them. An explicit schedule/place key wins. Lint: a declared tool\'s columns must exist on the table.',B.l,null,!1)
B.hMg=new A.D("graftsTable",B.b4,'ideasgraft-1026 (classic mode): opt-in GRAFTS \u2014 a table of typed containment edges {graftFromColumn: branch, graftToColumn: row, graftTypeColumn: graftType} attaching a row as a leaf under extra branches. The row menu and filing strip gain "Also file under\u2026" (tick/untick places). parentColumn stays the single primary home; grafting under the row itself or anything under it is refused.',B.l,null,!1)
B.hDQ=new A.D("graftFromColumn",B.L,'graftsTable column holding the BRANCH id (default "fromId").',B.l,null,!1)
B.i2B=new A.D("graftToColumn",B.L,'graftsTable column holding the grafted row id (default "toId").',B.l,null,!1)
B.hVc=new A.D("graftTypeColumn",B.L,'graftsTable column holding the edge type (default "type").',B.l,null,!1)
B.hU5=new A.D("graftType",B.Q,'Edge type value meaning "grafted under" (default "graft").',B.l,null,!1)
B.i2O=new A.D("badgeColumn",B.L,"Generic badge: any row whose <badgeColumn> boolean field is true shows a small badge icon, independent of edges-mode/sharing \u2014 works on any explorer (e.g. flag rows with an inherited property).",B.l,null,!1)
B.hUQ=new A.D("starColumn",B.L,"Generic star: every row gets a tap-to-toggle star icon bound to this boolean column, and starred rows sort ahead of unstarred siblings at the same level (folders still sort before files).",B.l,null,!1)
B.i3X=new A.D("shareAware",B.a8,"Opt-out (default true): when the host has wired a ShareInfoProvider/AccessResolver (project sharing), this explorer shows the share people-chip + accent stripe and honors capability gating on add/rename/delete/drag. Set false to exempt this explorer even when the host's hooks are wired globally. Inert when the host wires no hooks.",B.l,null,!1)
B.hWj=new A.D("nameFromColumn",B.L,'Opt-in: a leaf whose name column is empty shows the first line of THIS column (the note body) as its name, else a localized "New note". Display only; nothing is written.',B.l,null,!1)
B.hV8=new A.D("quickCreate",B.a8,"Opt-in quick capture: New file creates an empty-named leaf in the current folder (or top level), selects it, and skips the rename prompt \u2014 no folder choice up front. Pair with nameFromColumn.",B.l,null,!1)
B.hJZ=new A.D("fileNameField",B.a8,'Opt-in (Suite): New file is created with an EMPTY name, skips the Rename prompt and opens straight into its detail view, which shows a boxed name field on top (italic "No File Name" placeholder; typing names the file). Empty names read as italic "No File Name". Folders keep the Rename prompt.',B.l,null,!1)
B.hH9=new A.D("moveToFolder",B.a8,'Opt-in, parentColumn mode: file items into folders after the fact \u2014 row \u22ee "Move to folder\u2026" (centered popup, works on phone) plus drag a row onto a folder (mouse drag / touch long-press) and a top-level drop zone while dragging. One undoable parent write + Undo toast.',B.l,null,!1)
B.i3M=new A.D("dragReparent",B.a8,"Edges-mode: drag a row onto another to re-parent it \u2014 moves the grabbed contains-edge to the drop target, cycle-guarded with undo.",B.l,null,!1)
B.i5x=new A.D("fileValue",B.Q,'kindColumn value stamped on a new leaf (non-folder); default "file" \u2014 set when kindColumn is an enum without a literal "file" value.',B.l,null,!1)
B.hTD=new A.D("initiallyExpanded",B.a8,"Open every folder on first build (a grouped-list feel) instead of a collapsed tree the user must expand.",B.l,null,!1)
B.hF7=new A.D("railTitleHidden",B.a8,"dispshared-1125: the rail heading text is not drawn (the app bar names the screen); its add buttons stay. Default false.",B.l,null,!1)
B.hN3=new A.D("emptyTitle",B.Q,"dispshared-1125: an empty rail shows this headline, emptyText below it and an add button labelled emptyActionLabel (default newFileLabel). Absent = the one-line hint.",B.l,null,!0)
B.i0_=new A.D("emptyText",B.Q,"dispshared-1125: see emptyTitle.",B.l,null,!0)
B.i6j=new A.D("emptyActionLabel",B.Q,"dispshared-1125: see emptyTitle.",B.l,null,!0)
B.i1A=new A.D("listOnly",B.a8,'Render just the rail \u2014 a clean full-width list with no always-shown detail pane; a row\'s \u22ee "View detail" opens the detail node in a dialog on demand.',B.l,null,!1)
B.hZj=new A.D("convertible",B.a8,'Row menu offers "Make a folder" (on a file) / "Make a file" (on a folder, \u22641 child) \u2014 spins owned child rows + carry-column content to/from a fresh child so nothing is lost.',B.l,null,!1)
B.hRg=new A.D("ownedTables",B.W,"Convertible: child tables this node OWNS via a column == the node id (e.g. {table: updates, column: nodeId}); their rows re-parent on convert.",B.l,null,!1)
B.hDP=new A.D("carryColumns",B.W,"Convertible: column names whose value travels to the new child on file\u2192folder, and back on folder\u2192file.",B.l,null,!1)
B.hP0=new A.D("convertToFolderLabel",B.Q,'Convertible: row-menu label for the file\u2192folder action (default "Make a folder"); may be a {lang: text} map.',B.l,null,!0)
B.hEh=new A.D("convertToFileLabel",B.Q,'Convertible: row-menu label for the folder\u2192file action (default "Make a file"); may be a {lang: text} map.',B.l,null,!0)
B.hLa=new A.D("previewLines",B.aS,"Descriptive leaf rows: show the name across up to N lines (default 1) \u2014 folders always stay 1-line.",B.l,null,!1)
B.hPa=new A.D("titleMaxLines",B.aS,"Ceiling on how many lines a leaf row TITLE itself may wrap to (default 2, minimum 1) \u2014 independent of previewLines, which still governs the comment preview below it. A narrow tree column can set this to 1 so a row stays a compact title + single preview line instead of stacking a 2-line title on top of a multi-line preview.",B.l,null,!1)
B.i1g=new A.D("itemViewOnCreate",B.a8,'Adding a new leaf opens the read-only item view (title autofocused, comment placeholder) instead of the classic auto-"Rename" popup; abandoning it with both fields still blank deletes the row outright instead of leaving it "Untitled". Folders are unaffected \u2014 they keep the Rename prompt.',B.l,null,!1)
B.hWg=new A.D("titleFromFirstLine",B.a8,"Opt-in (needs itemViewOnCreate + commentColumn): a new leaf saved from the item view with an empty title takes its title from the first line of the comment/body (same rule as the notepad prop of the same name; a typed title is never overwritten).",B.l,null,!1)
B.hWr=new A.D("titleAutoColumn",B.L,'Memo column for explorer titleFromFirstLine (default "titleAuto"); keep it equal to the detail notepad\'s titleAutoColumn.',B.l,null,!1)
B.i2s=new A.D("commentColumn",B.L,"Optional free-text column shown as a second preview line under a leaf row's title (real content, or a grey-italic \"Comment\" placeholder when empty) and, with itemViewOnCreate, as the item view's comment box.",B.l,null,!1)
B.hKW=new A.D("commentEmptyText",B.Q,'What the tree-row preview line says for a row whose commentColumn is empty. Unset keeps the grey-italic "Comment" placeholder; an empty string shows no second line; text may be a {lang: text} map.',B.l,null,!0)
B.hYx=new A.D("tags",B.W,'Leaf rows: colored chips beneath the name, pairing with previewLines for a "cards" look in a flat list.',B.l,null,!1)
B.hPm=new A.D("statusColumn",B.L,'Status quick-set: when set, a row\'s \u22ee menu offers "Status: <value>" per statusOptions entry, writing it to this column (one undo step).',B.l,null,!1)
B.hEL=new A.D("statusOptions",B.W,"List of status values offered by the statusColumn quick-set menu.",B.l,null,!1)
B.hMc=new A.D("prioColumn",B.L,'Priority quick-set (priolanes2-0726): same idiom as statusColumn \u2014 a row\'s \u22ee menu offers "Priority: <value>" per prioOptions entry (plus a Clear item once set), writing it to this column (one undo step). Engine-generic; Dispatch wires it to `prioLane`.',B.l,null,!1)
B.i1b=new A.D("prioOptions",B.W,"List of priority values offered by the prioColumn quick-set menu.",B.l,null,!1)
B.hGx=new A.D("prioLabels",B.W,"Optional {value: label} display overrides for prioOptions entries; unset values show their raw string.",B.l,null,!1)
B.hSO=new A.D("recursive",B.a8,'An item can have BOTH its own detail AND children (no folder/file split) \u2014 every selected item shows its detail, any item with children is expandable, and "New <item>"/addItems add a child of the selected item.',B.l,null,!1)
B.i4K=new A.D("ownerColumn",B.L,"When set AND a rowId is injected (this explorer is itself a master-detail DETAIL child), the list filters to rows whose value in this column equals that injected id, and new rows are stamped with it.",B.l,null,!1)
B.i48=new A.D("detailedView",B.a8,"Two-level rail: column 2 (contents) offers a Directory \u27f7 Detailed toggle in its header \u2014 compact rows vs. a per-row progress DASHBOARD (status chip, progress bar, subtask/log-entry counts, the existing `tags` chips for priority/importance/due/assignee, and a one-line latest-activity preview), plus a compact done/active/queued rollup summary + bar at the top of the column for the open folder. Reads the existing showProgress rollup cache; never a second board walk.",B.l,null,!1)
B.dvg=s(["plain","rich"],t.s)
B.hTv=new A.D("folderCardStyle",B.bG,'detailedView: folder-row card style. "plain" (default, unchanged) | "rich" \u2014 primary-tinted folder surface, badge icon, a "N tasks \xb7 M sub-projects \xb7 K files" counts line (files = whole-subtree attachment count), a one-row chip strip of the folder\'s direct attachments (leafAttachmentKinds; omitted when dense) and a "No tasks yet" line for task-less folders.',B.dvg,null,!1)
B.hNh=new A.D("folderCardImageColumn",B.Q,'folderCardStyle "rich": column on an image attachment row holding its picture (data-uri/url or [{mime,data}] list) for the chip thumbnail. Default "attachment".',B.l,null,!1)
B.djh=s(["directory","detailed"],t.s)
B.hEB=new A.D("defaultContentsView",B.bG,'detailedView: initial column-2 toggle state. Unset \u2192 "directory" (unchanged compact rows on first open).',B.djh,null,!1)
B.hS1=new A.D("projectOverview",B.a8,"Opt-in PER-PROJECT overview dashboard \u2014 a third Tasks \u21c4 Overview segment in column 2's (contents) header, alongside the existing detailedView Directory/Detailed toggle. Off by default so no existing applet's UI changes. When on, selecting a project can switch its contents column to a computed bar/pie breakdown of every item in that project's contains-subtree. See overviewTagsColumn/overviewTypeColumn for the two breakdown columns.",B.l,null,!1)
B.hY4=new A.D("valueLabels",B.W,"Opt-in raw-value \u2192 display map for rendered DATA VALUES (tree row status/tag chips, the projectOverview by-status/by-tag/by-type chart bucket labels): {raw: text-or-{lang:text}} or column-keyed {column: {raw: ...}}, resolved against the ambient locale; unmapped values render exactly as before (passthrough, never blank). Display-only \u2014 stored values, filter payloads and tag `colors` keys stay RAW.",B.l,null,!1)
B.hUA=new A.D("overviewTagsColumn",B.L,"projectOverview: the multi-value (List<String>) column the overview's \"by tag\" bar chart buckets on \u2014 each item can carry more than one tag, so every tag it holds counts once in that tag's bucket (a scalar column works too; each row then counts once under its own value). Unset hides the tag breakdown.",B.l,null,!1)
B.i0I=new A.D("overviewTypeColumn",B.L,'projectOverview: the scalar column the overview\'s "by type" bar chart buckets on (e.g. group/task/note/goal/milestone/...). Unset hides that breakdown.',B.l,null,!1)
B.hYc=new A.D("overviewMarkerColumns",B.kV,"projectOverview: boolean columns (e.g. bottleneck/blocked) whose true value marks an item as needing attention in the overview's \"Needs attention\" section \u2014 one group per configured column, titled by that column's own schema label. Empty (default) adds no marker groups; the no-responsible-person and stale groups are always generic and still show.",B.l,null,!1)
B.hTa=new A.D("overviewDueColumn",B.L,"projectOverview: the date column read for the overview's Overdue needs-attention group. Unset skips the Overdue group entirely.",B.l,null,!1)
B.hJv=new A.D("overviewLogColumn",B.L,"projdash-0810 fix-forward: boolean column marking a descendant as LOG CHATTER (an entrythread comment/reply) rather than a first-class project item \u2014 the SAME column an entrythread node's own opt-in `logEntryColumn` stamps true on every composed entry. When set, projectOverview's item population (`_overviewDescendants`) excludes flagged rows from the headline count, the status/tag/type breakdowns and the item list \u2014 a task with 300 log comments no longer inflates \"items total\" or the active-status pie. Unset (default) is a no-op: nothing is excluded, matching pre-fix behavior. Attachment-kind children (`leafAttachmentKinds`) are excluded unconditionally, no config needed.",B.l,null,!1)
B.hIt=new A.D("activeStatus",B.Q,'detailedView: statusColumn value counted as "active" in the active/queued split (default "active").',B.l,null,!1)
B.hJ5=new A.D("queuedStatus",B.Q,'detailedView: statusColumn value counted as "queued" (default "queued").',B.l,null,!1)
B.hEU=new A.D("activityColumn",B.L,'detailedView: column holding the text shown as a row\'s one-line latest-activity/comment preview (default "comment").',B.l,null,!1)
B.i_M=new A.D("activityTimeColumn",B.L,'detailedView: column used to find the most recent child/descendant for the latest-activity preview (default "postedAt"); must resolve to a parseable date/dateTime column.',B.l,null,!1)
B.i_F=new A.D("alwaysShowDetail",B.a8,'Two-level, wide layout: when a project (folder) is selected/opened and no child ends up auto-selected, show the project\'s OWN detail (requires `recursive`) instead of the "pick a task" placeholder.',B.l,null,!1)
B.i72=new A.D("detailKindLabel",B.a8,'Show a small "Project"/"Task" header label above the detail pane\'s content \u2014 nouns derived from newFolderLabel/newFileLabel (strip a leading "New "), override via folderNoun/fileNoun.',B.l,null,!1)
B.hWG=new A.D("folderNoun",B.Q,'detailKindLabel override: the noun shown for a folder ("Project"). May be a {lang: text} map.',B.l,null,!0)
B.hXZ=new A.D("fileNoun",B.Q,'detailKindLabel override: the noun shown for a leaf ("Task"). May be a {lang: text} map.',B.l,null,!0)
B.i_f=new A.D("settingsAction",B.W,"Opt-in: {fn, args?, label?} \u2014 a gear affordance shown next to a selected FOLDER's detail header, fired with that row's id (like menuActions, but a single, separate surface for FEATURE settings \u2014 e.g. sharing/members \u2014 kept distinct from the row \u22ee menu's quick actions and from the attributes/edit-details form's data fields).",B.l,null,!1)
B.hG9=new A.D("rootDashboard",B.a8,'Two-level rail: the synthetic root ("Projects", nothing selected) gets a COMPUTED cross-project progress dashboard as its detail \u2014 overall done/active/queued rollup plus one row per top-level project \u2014 built from the existing showProgress rollup cache. The root stays synthetic: no new record, no reparenting.',B.l,null,!1)
B.hGK=new A.D("filterable",B.a8,"Opt-in per-column filtering of the TASKS/children column (the two-level rail's column 2, and the narrow children-directory list) via the unified Add-filter engine \u2014 mirrors agenda/tree/cards/report's own \"filterable\" opt-in (AddFilterBar<Record> + applyColFilters). Off (default) renders exactly as before. Session-scoped state only; the pinned strip and the projects (column-1/root) list are never filtered.",B.l,null,!1)
B.i_r=new A.D("filterGroups",B.W,'Config-defined sections for the Filter config view\'s field list: [{"label": "Workflow" or {"en": ..., "ko": ...}, "columns": ["type", "status"]}]. Listed groups render first in config order (columns in listed order); columns no group lists fall back to the automatic sections (Status & lanes / People / Dates / Text / More). Absent = automatic sections only.',B.l,null,!1)
B.hGE=new A.D("filterPresets",B.W,'Built-in filter presets shipped by the applet: [{"name": "Done" or {"en": ..., "ko": ...}, "orMode": false, "filters": {"status": {"selected": ["done"]}}}] (the saved-preset JSON shape). Listed ahead of the user\'s own presets, lock-marked and read-only (no rename/overwrite/delete; never stored with user presets).',B.l,null,!1)
B.i0b=new A.D("statusLegend",B.W,'Opt-in (dufb-1017): [{"value": "superseded", "label": {lang: text}, "meaning": {lang: text}}] \u2014 an info button beside the contents column\'s filter/sort pops a floating list of every status with its one-line meaning.',B.l,null,!1)
B.hJd=new A.D("detailGutter",B.aS,"dispfb-1018: horizontal gutter (px, house token scale 4/8/12/16/24) applied at the DETAIL PANE container so every section inherits it instead of sitting flush against the panel divider. Absent/0 = unchanged.",B.l,null,!1)
B.hJy=new A.D("selectShowsProject",B.a8,"Opt-in (dufb-1017, needs recursive): selecting a project always opens the project's own view in the wide detail pane \u2014 never a bare row selection or a lingering task of it.",B.l,null,!1)
B.i3j=new A.D("wrapRows",B.a8,"Opt-in (dufb-1017, widened dispinline-1026): every LEAF row (tiles, directory rows, favorites, tree) shows the title and the row's own commentColumn fully wrapped (no clamp); ONE tap on that text edits it in place (Enter/blur/outside-tap commits, Esc cancels). Wide: the same tap also selects the row so the detail pane opens beside the editor. Phone: a tap OPENS the item (tap-opens standard); a trailing open button is an extra explicit door.",B.l,null,!1)
B.dyB=s(["tap","doubleTap"],t.s)
B.hFV=new A.D("inlineEditOn",B.bG,'wrapRows only (dispux-1121): what starts the wide inline title edit. "tap" (default) = one tap selects and edits (dispinline-1026). "doubleTap" = one tap only selects/opens the row; a second tap on the same title starts the edit. Row-menu Rename unaffected.',B.dyB,null,!1)
B.hZD=new A.D("wideBackSteps",B.a8,"Opt-in (dispux-1121): on WIDE layouts system / browser Back steps open item -> its folder's list/overview -> parent folder -> root, and only at the root lets the pop leave the applet (phone layouts already step this way). Off = a wide Back leaves the applet.",B.l,null,!1)
B.a5z=s(["compact"],t.s)
B.hWc=new A.D("contentsToolbar",B.bG,'Opt-in (dispux-1121): "compact" folds the contents column chrome into at most 3 rows \u2014 header with the parent crumb folded into the title ("\u2039 Projects / Name"), ONE single-line toolbar (+ New, filter chip showing the active preset with a count badge, star, sort, \u22ee legend), and a one-line progress summary. The filter chip opens the full Add-filter surface. Default/absent = today\'s stacked layout.',B.a5z,null,!1)
B.i1H=new A.D("detailHeader",B.bG,'Opt-in (dispux-1121): "compact" puts the detail header\'s kind, crumb, #id, edit, expand and \u22ee actions on ONE row and the title on its own full-width line below. Default/absent = today.',B.a5z,null,!1)
B.hLP=new A.D("rowControls",B.bG,'Opt-in (dispux-1121): "compact" tree rows show a leading status dot (not the pill), only \u22ee inline (hover/selected), and a star only on starred rows; Star/Unstar and tags live in the \u22ee menu. Default/absent = today.',B.a5z,null,!1)
B.dv6=s(["peek"],t.s)
B.i7_=new A.D("todayChipAction",B.bG,'Opt-in (dispux-1121): "peek" makes a Today strip chip open a popup in place (anchored under the chip; a centered dialog under 600 px) titled with the chip label + count and listing its items (title + parent project, max ~8 visible then scroll). Tapping an item closes it and selects that item in this explorer; the last row "Open Today" fires todayAction. Empty = "Nothing here right now." Default/absent = a chip tap fires todayAction.',B.dv6,null,!1)
B.i4H=new A.D("rememberPosition",B.a8,"Opt-in (dispux-1121): remember the selected folder, selected item and open folder path for the app session (in memory, keyed by node id + table) and restore them when the explorer is re-mounted (e.g. Projects -> Today -> Projects). Ids that no longer exist fall back to the root silently. Off = a fresh mount starts at the root.",B.l,null,!1)
B.hVV=new A.D("detailWideColumns",B.a8,"Opt-in (dispux-1121): when the detail pane content is >= 900 px wide, the detail column's first child (the record) splits into a full-width header (action row + title) over two top-aligned columns in one shared scroll view: LEFT (40%, max 460) all record fields (no \"+N more\" collapse), RIGHT every following detail child (log, sub-items, overview, rules). Narrower = today's stack. Needs the detail to be a column whose first child is a record.",B.l,null,!1)
B.i2R=new A.D("detailWideBalance",B.W,"Opt-in (disppage-1125), with detailWideColumns: split only when both columns would be full - at least minFields filled record fields (default 8; values in the record's hideValues do not count) and at least minEntries children (default 3). Otherwise the fields stay a chip row under the title and the log gets the width. true = the defaults.",B.l,null,!1)
B.hUz=new A.D("railWideColumns",B.a8,'Opt-in (dispux-1121): when the tree rail is >= 720 px wide (the contents and detail panes folded) each hybrid tree row keeps its name at the left (capped ~420 px) and gains right-aligned Status, Progress (folders: the folder-card done/active/queued summary) and Due columns under a one-line column header. Under 720 px nothing changes. Needs rowStyle "hybrid" with a treeRail.',B.l,null,!1)
B.duZ=s(["panels"],t.s)
B.i3e=new A.D("layout",B.bG,'Opt-in (disppanels-1121): "panels" = ONE panel component repeated left to right (the user picks how many, see `panels`), one view-wide toolbar (Today counters, filter chip, star, sort, density, \u22ee) and the detail beside the panels. Panel 1 lists the root; clicking an item with children opens it into the next panel (the last panel expands it in place); an item id shows at most once across the panels. Nothing selected = no detail, the last panel takes the room. Under 640 px: one panel with the phone drill-down. Absent = every other layout, unchanged.',B.duZ,null,!1)
B.hP8=new A.D("panels",B.W,'layout "panels" only: {"default": 2, "max": 3, "density": "comfortable"|"compact", "chips": ["priority","importance"], "rootTitle": true, "countLabel": "project|projects"}. `rootTitle` false = the root panel header shows its item count (with `countLabel`, else `childCountLabel`, e.g. "4 items") where the title was, then "+" and "\u22ee" (the host app bar already names the screen). The user\'s count (1..max) and density persist per applet per device under `explorerPanels:<node id>` (BoardState explorerPanelCount / setExplorerPanelCount drive the host control); `chips` columns show on a row (as "<column> <value>") only when the value differs from the schema default. `emptyDetail` true (dispopen-1125): nothing opens at start; with nothing selected the right side shows one "pick an item" line; the full-width table is a chosen "Table" view (BoardState explorerPanelTable / requestExplorerPanelView). `resizeColumns` true: Status / Progress / Due resize by dragging the header dividers, widths persist per node. foldEmptyToday true (dispshared-1125): on the Today list empty groups fold into one dim line followed by todayEmptyHint (text or {lang: text}). `phoneControls` "merged" (dispphonerows-1126): below 600 px the toolbar row and the panel header are ONE row (count line with the status counts, filter, Sort and folders, +, one \u22ee with star / density / legend / archived); rows show "example" on the detail line, one "Saved on this device only" foot line (with Sign in when the host registers a `signIn` callback) instead of a per-row "Local only", and no per-row \u22ee when the row card opens on long-press. Absent = unchanged.',B.l,null,!1)
B.hXG=new A.D("findInFolder",B.a8,'Opt-in (dispsearch-1019): a "Find in folder" row-menu entry on folders that scopes a find box to that folder\'s subtree, with a tappable ancestor-path line on every result. Off = unchanged.',B.l,null,!1)
B.hZ_=new A.D("searchResultPath",B.a8,"Opt-in (dispsearch-1019): show a tappable ancestor-path line (tap a segment to reveal that folder in the tree) on rows of the app-header search results list. Implied by findInFolder.",B.l,null,!1)
B.hUo=new A.D("compactRowMenu",B.a8,'Opt-in (dufb-1017): fold the row menu \u2014 create entries under one "New \u25b8" door, copy entries under "Copy \u25b8", organize/host extras (move to top, convert, pin, menuActions) under "More \u25b8". A group with one entry stays inline. Off = the flat menu.',B.l,null,!1)
B.hOO=new A.D("detailSettingsIcon",B.a8,'Opt-in (disptidy-1125, with detailHeader "compact" and settingsAction): a project icon on the item page action row of a FOLDER opens settingsAction (Project settings). Off = reached only from the page and row menus.',B.l,null,!1)
B.hQB=new A.D("rowMenuCascade",B.W,'Opt-in (dispmenu-1125, with rowMenu "newday"): one card menu at every level \u2014 \u22ee, right-click and long-press open the same card; sub-menus (New, Copy, Move, Lane, Status, More) open beside their row at the same width. true, or a map of label maps for the New rows. Off = the card plus the old "More actions" list.',B.l,null,!1)
B.aHU=s(["newday"],t.s)
B.hWI=new A.D("rowStyle",B.bG,'Opt-in (disphybrid-1111) "newday": LEAF rows in the detailed contents list take New Day\'s look \u2014 a coloured lane edge from prioColumn (rowLaneColors / rowLaneFallback; off-list values are neutral), a \u25b8/\u25be inline peek at what is inside, "N inside" / "N comments" (rowCommentKinds + overviewLogColumn), the tag chips and the overviewDueColumn date. Folder cards are unchanged. Unset = the existing detailed tile.',B.aHU,null,!1)
B.hXh=new A.D("rowMenu",B.bG,'Opt-in (disphybrid-1111) "newday": right-click (and a long-press; on touch, lifting a row and releasing it in place) opens the hybrid row menu \u2014 title + counts, Copy as text (outline with items inside and comments), Lane (prioOptions), Status \u203a, Move into project\u2026 (edges + dragReparent: re-points only the edge from the parent being viewed), Star, Open \u2014 and "More actions \u203a" with the full existing row menu. Unset = the existing menu.',B.aHU,null,!1)
B.hKG=new A.D("rowLaneColors",B.W,'disphybrid-1111: {lane: "#RRGGBB"} overrides for the hybrid row\'s lane edge (defaults: immediate, now, next, queued, later).',B.l,null,!1)
B.hPF=new A.D("rowLaneFallback",B.W,"disphybrid-1111: {status: lane} \u2014 the lane an EMPTY prioColumn reads as for the edge colour (display only, never written).",B.l,null,!1)
B.hNF=new A.D("rowCommentKinds",B.W,'disphybrid-1111: kindColumn values counted as comments on a hybrid row (with overviewLogColumn-marked rows); every other child counts as "inside".',B.l,null,!1)
B.hLd=new A.D("todayStrip",B.W,'disphybrid-1111: [{id, label, groupLabel?, color "#hex", filter}] \u2014 counted chips above the tree (wide) / under the top bar (phone, not on the item page), and the groups of the defaultView "today" list. filter: {column, value | in | exists | empty} or a list (ANDed); values are literal (no today/now tokens); "$playerId" binds to the signed-in player, else defaultActor, else the bucket is empty.',B.l,null,!1)
B.i5j=new A.D("todayAction",B.W,"disphybrid-1111: action fired when a Today chip is tapped outside the Today view (e.g. goto the Today screen); that screen opens focused on the tapped bucket.",B.l,null,!1)
B.i6Z=new A.D("defaultFilterPreset",B.W,'Opt-in (dufb-1017): the filterPresets entry (int index or English name) applied to the tasks column on open. The Presets menu then offers "Set current filter as my default" (stored per user/applet) and "Reset default" (back to this preset).',B.l,null,!1)
B.hYI=new A.D("followSelection",B.a8,"Two-way sync with `board.settings['sel:<table>']`: an external write (e.g. a notepad's resolved [[Wiki Link]] tap) selects + reveals that row here; picking a row here publishes back to the same setting. Off by default (no behavior change).",B.l,null,!1)
B.i74=new A.D("id",B.Q,"This node's handle \u2014 required for the explorerSetPanelVisible runtime action (and panelChannel) to target it (an id-less explorer still renders, just not runtime-controllable).",B.l,null,!1)
B.i51=new A.D("panelChannel",B.a8,"Opt-in (roundb-0720-eng): the three rail panels (tree/contents/detail) collapse state is read/written through BoardState.effectiveExplorerPanelVisible/setExplorerPanelVisible (runtime-overridable via the explorerSetPanelVisible action) instead of pure session-local widget state. Requires this node's `id`. Off (default): byte-identical to today, pure private State.",B.l,null,!1)
B.hWO=new A.D("twoLevel",B.a8,"Two-column rail: column 1 lists top-level folders/projects, column 2 the selected one's children, before the detail view.",B.l,null,!1)
B.hGb=new A.D("autoSelectFirstChild",B.a8,"On selecting a folder, immediately select its first child so the detail pane is never empty.",B.l,null,!1)
B.hVA=new A.D("colorColumn",B.L,"Optional per-row colour column (ramp name or #hex) tinting the rail entry.",B.l,null,!1)
B.i5c=new A.D("emojiColumn",B.L,"Optional column holding a leading emoji shown on each rail entry.",B.l,null,!1)
B.hR2=new A.D("cardRows",B.a8,"Render each rail row as a rounded card surface (margin + border) instead of a flat list row, so an items panel reads as pretty cards.",B.l,null,!1)
B.hKC=new A.D("clearSelectionOnBackgroundTap",B.a8,'With followSelection on, tapping empty rail background clears the current sel:<table> selection (same as the "Scoped to: X \u2715" chip). On by default when followSelection is set; set false to opt a followSelection explorer out.',B.l,null,!1)
B.hX5=new A.D("newValues",B.W,'Values stamped on every new leaf (New <file> and addItems), token-resolved like a composer write (e.g. {"createdBy": "$playerId"}); addItems\' own "values" override these per-item.',B.l,null,!1)
B.hMe=new A.D("focusRoot",B.a8,'mokufb7-1004-B: while a row is open the rail shows only its top-level ancestor with that row\'s children nested (always open); the rail title becomes a back-link to the full list (the open row stays open); narrow layouts show the family as tabs. Leaves with children expand; "New <file>" always makes a top-level row; deleting a row with children asks delete-all vs keep. Classic parentColumn mode only. Off = unchanged.',B.l,null,!1)
B.hHy=new A.D("childAdd",B.W,'With focusRoot: {label, icon?, options?:[{label, icon?, action}], action?} \u2014 the "+ New <child>" row under the focused family and in a top-level row\'s menu. Actions fire with the top-level row id + the surface `locale`; no action = a plain child row. Hidden when the table lacks parentColumn. Labels may be {lang: text} maps.',B.l,null,!1)
B.hMN=new A.D("childIcon",B.Q,'With focusRoot: icon for child rows (e.g. "branch").',B.l,null,!1)
B.hSF=new A.D("childNoun",B.Q,'With focusRoot: children\'s noun "singular|plural" for the delete-with-children choice; may be a {lang: text} map.',B.l,null,!0)
