B.hce=new A.dp("explorer","Master-detail file browser: a collapsible left folder-tree (nested via a self-referential parent column) drives a configurable detail view of the selected file. New/rename/delete (recoverable Trash) on the rail.",B.dvB,!1)
B.hVu=new A.D("table",B.b4,'Files table (default "files").',B.l,null,!1)
B.hXs=new A.D("fileId",B.Q,'The open file\'s id; usually injected as "rowId" by an explorer detail.',B.l,null,!1)
B.hUC=new A.D("parentColumn",B.L,'Self-referential parent id linking pages to their file (default "parentId").',B.l,null,!1)
B.i6i=new A.D("nameColumn",B.L,'Page-name column (default "name").',B.l,null,!1)
B.hKZ=new A.D("orderColumn",B.L,'Order column for pages (default "order").',B.l,null,!1)
B.hJF=new A.D("kindColumn",B.L,'Column marking a row as a page (default "kind").',B.l,null,!1)
B.i2n=new A.D("pageValue",B.Q,'kindColumn value that means "page" (default "page").',B.l,null,!1)
B.hOu=new A.D("pageLabel",B.Q,'Noun for a page: Page / Canvas / Sheet (default "Page").',B.l,null,!1)
B.hSK=new A.D("fileIsFirstPage",B.a8,"Treat the file row itself as page 1 (default true).",B.l,null,!1)
B.hLD=new A.D("stripOnlyWhenExtra",B.a8,"Show the page strip only when the file has extra page rows (default false).",B.l,null,!1)
B.i3L=new A.D("detail",B.vt,'Editor rendered for the active page; "rowId"/"table" are injected.',B.l,null,!1)
B.dfl=s([B.hVu,B.hXs,B.hUC,B.i6i,B.hKZ,B.hJF,B.i2n,B.hOu,B.hSK,B.hLD,B.i3L],t.G)
B.hdO=new A.dp("pages","A page strip for an open file (companion to explorer): switch / add / rename / delete the pages inside one file, with a configurable detail editor for the active page. Same strip drives a document's pages, a drawing's canvases, or a spreadsheet's sheet-tabs.",B.dfl,!1)
B.b4k=new A.D("table",B.b4,"The table holding the document/page row.",B.l,null,!1)
B.b4G=new A.D("rowId",B.Q,"Row to edit; usually injected by a pages/explorer detail.",B.l,null,!1)
B.hVE=new A.D("column",B.L,'Column storing the document Delta JSON (default "body").',B.l,null,!1)
B.hLY=new A.D("page",B.a8,'Page-look surface \u2014 a centered max-width "paper". On by default; set false for a plain full-bleed editor.',B.l,null,!1)
B.i6n=new A.D("fonts",B.W,'Override the font-family picker: {"Label": "Family", \u2026}. Omit to use the bundled document fonts (Lora, Inter, Space Grotesk, IM Fell English, Special Elite, Rye).',B.l,null,!1)
B.i5P=new A.D("title",B.Q,'Document title used when printing (default "Document"); may be a {lang: text} map.',B.l,null,!0)
B.hNf=new A.D("readOnly",B.a8,"View only: no formatting toolbar, margin ruler, Page setup or page breaks, and the editor refuses edits (default false). Page setup and page breaks are stored inside the document body.",B.l,null,!1)
B.d6H=s([B.b4k,B.b4G,B.hVE,B.hLY,B.i6n,B.i5P,B.hNf],t.G)
B.hc9=new A.dp("richdoc","A true WYSIWYG rich-text editor (flutter_quill) for one row's column \u2014 toolbar formatting (bold/italic/underline/strike/highlight/colour/font/headings/lists/links) stored as Quill Delta JSON. Migrates an existing Markdown value in on first open. The Docs page editor; Notes stay on `notepad`/Markdown.",B.d6H,!1)
B.hQV=new A.D("column",B.L,'Text column to edit (default "body").',B.l,null,!1)
B.hMJ=new A.D("titleColumn",B.L,"Optional column shown as the editor heading (inline when chromeless).",B.l,null,!1)
B.hVQ=new A.D("firstLineTitle",B.a8,"Opt-in Apple-Notes look (needs titleColumn; implies titleFromFirstLine): the first body line is the note title, set large + bold in the editor, no separate header title; an empty note is focused ready to type. A note with an explicit (manual/legacy) title keeps the classic header title and a plain body. No data is migrated.",B.l,null,!1)
B.hTp=new A.D("titleFromFirstLine",B.a8,"Opt-in (needs titleColumn): on each body save the title follows the first non-empty body line (~60 chars, markdown markers stripped) until the title is changed any other way (a rename) \u2014 then the manual title wins permanently. Pages with a different pre-existing title are never touched; wiki-links re-resolve on a derived change.",B.l,null,!1)
B.i4N=new A.D("titleAutoColumn",B.L,'Column remembering the last title derived by titleFromFirstLine (default "titleAuto"). A stored title that differs from it is treated as manual.',B.l,null,!1)
B.hJ2=new A.D("placeholder",B.Q,"Empty-editor hint text; may be a {lang: text} map.",B.l,null,!0)
B.hFr=new A.D("editedByColumn",B.L,"Opt-in: on a real inline edit, stamp this ref column with `editedBy` (the pre-resolved actor id).",B.l,null,!1)
B.i5J=new A.D("editedAtColumn",B.L,"Opt-in: date column stamped today alongside editedByColumn on an edit.",B.l,null,!1)
B.i1I=new A.D("editedBy",B.Q,"Pre-resolved actor id the host passes for edit stamping (a users row).",B.l,null,!1)
B.hTm=new A.D("saveMode",B.Q,'Initial save mode: "live" (continuous, default) or "manual" (Save).',B.l,null,!1)
B.hXn=new A.D("chromeless",B.a8,"Hide the notepad's own header (Write/Preview, Auto/Manual, Save) so a host (e.g. an expandable card) owns the edit chrome; the title then renders inline.",B.l,null,!1)
B.hUY=new A.D("editing",B.a8,"Host-driven edit gate: false = read-only Markdown view, true = editable. Omit to self-manage (the default).",B.l,null,!1)
B.i0H=new A.D("readOnly",B.a8,"Force the read (Markdown) view.",B.l,null,!1)
B.hF0=new A.D("autoHeight",B.a8,"Size to content (no Expanded) for inline use \u2014 a short note stays short; the editor grows with its text.",B.l,null,!1)
B.hJ0=new A.D("toolbar",B.a8,"Docs-grade authoring: show a Markdown formatting toolbar (bold, italic, headings, lists, quote, code, link) in Write mode. Off by default \u2014 Notes stays minimal; Docs opts in.",B.l,null,!1)
B.hTl=new A.D("document",B.a8,"Hold the editor + reading view to a centered page width for a real document feel. Off by default (full-bleed notes).",B.l,null,!1)
B.i_C=new A.D("colorColumn",B.L,'Sticky-note colour: show a quick colour strip in the editor that writes this column (a ramp name like "amber"). Colours come from the column\'s options. Off by default.',B.l,null,!1)
B.i1h=new A.D("liveFormat",B.a8,"Live formatting: render Markdown styling (bold / italic / headings / code / strikethrough) in the editor as you type, so the editor IS the preview. Off by default; Docs opts in.",B.l,null,!1)
B.hPN=new A.D("safeLinks",B.a8,'Safe rendered Markdown (Preview): [label](url) opens only http/https and only when tapped; a remote image shows a "Load image" button and is not fetched until tapped; file:/data:/relative links and images never load. Off by default (links inert).',B.l,null,!1)
B.hOX=new A.D("sourceFormatColumn",B.L,'Per-format SOURCE editor: names the row column holding the document\'s format. A value of html / xml / json / yaml turns the notepad into a source editor (monospace, line numbers, inline problems, Tree lens for xml/json/yaml, Format document for json/xml, Manual save by default). Any other value (txt, md, empty) leaves the notepad exactly as it is. Notes opts in with "boundFormat".',B.l,null,!1)
B.i6p=new A.D("dense",B.a8,"Compact inline field: no outer padding, starts one line tall, body-medium text \u2014 a quiet field for compose cards, not a big box.",B.l,null,!1)
B.hYM=new A.D("heading",B.a8,"Style the edit text as a heading (title-small) \u2014 pair with a title column so a card title reads as a heading, not body copy.",B.l,null,!1)
B.i0G=new A.D("autofocus",B.a8,"Focus the editor on mount with the cursor at the END \u2014 tap-to-edit flows get a ready cursor, no second tap.",B.l,null,!1)
B.hWV=new A.D("minLines",B.aS,"Starting height in LINES for the autoHeight editor (overrides the dense/default choice) \u2014 e.g. 3 gives a comment room to write while the read view stays compact.",B.l,null,!1)
B.hOR=new A.D("linksTable",B.b4,"Enables Obsidian-style `[[Title]]` wiki-links: an auto-maintained link-row index in this table (add/remove/update on every save), tappable resolved-link spans in Preview (writes `sel:<table>` \u2014 pair with an explorer's `followSelection` to jump there), and a `[[` title autocomplete while typing. Unset (default) \u2192 zero behavior change. If a merge (or any external write) ever leaves two linksTable rows with the same resolved title for the same FROM note, the sync keeps the FIRST row in table order and reaps the rest \u2014 deterministic, not arbitrary.",B.l,null,!1)
B.hH2=new A.D("linkFromColumn",B.L,'linksTable column holding the FROM note\'s id (default "fromId").',B.l,null,!1)
B.hVd=new A.D("linkToColumn",B.L,'linksTable column holding the resolved TO note\'s id, empty when unresolved (default "toId").',B.l,null,!1)
B.hKH=new A.D("linkTitleColumn",B.L,'linksTable column holding the link\'s literal target title text, kept even when unresolved (default "toTitle").',B.l,null,!1)
B.hQ5=new A.D("linkFromTitleColumn",B.L,'linksTable column that also receives the FROM note\'s own title (default "fromTitle") \u2014 kept in sync on every wiki-link sync pass and on rename of the source note. Lets a backlinks view label each row with the source without a join.',B.l,null,!1)
B.hFI=new A.D("onLinkTap",B.W,"Opt-in action spec { fn, args } fired when a plain Markdown `[label](target)` link (NOT a `[[Title]]` wiki-link, which uses linksTable instead) is tapped in Preview. `target` (the link's raw url/title text) substitutes any literal \"$value\" in args, same as textinput's action. Unset (default) \u2192 the link renders styled but inert, unchanged from before this prop existed.",B.l,null,!1)
B.hZi=new A.D("lazyBlocks",B.a8,"Opt-in LAZY read view: builds only on-screen Markdown blocks (ListView.builder) instead of the default eager build-everything-up-front view. For a genuinely long document (e.g. a full encyclopedia article) this is the fix for visible scroll lag. No effect when `readOnly`'s shrinkWrap (inline preview) applies. Off by default \u2014 zero behavior change for existing callers.",B.l,null,!1)
B.i1E=new A.D("jumpToSectionSetting",B.Q,'Opt-in "jump to section" (only acts when lazyBlocks is also true): names a board-settings key. When that setting\'s value changes to "<anything>::<heading text>" (the leading part just needs to change to force a re-jump on a repeated tap of the same section \u2014 e.g. a timestamp), the read view animate-scrolls to the first #/##/### heading block matching the text (trimmed, case-insensitive) at an ESTIMATED position \u2014 not pixel-exact.',B.l,null,!1)
B.i6o=new A.D("findEnabledSetting",B.Q,'Opt-in "Find in article" (only acts when lazyBlocks is also true): names a board-settings key an external affordance (e.g. a \u22ee "Find in article" action) toggles true/false to open/close an inline search bar rendered above the article. The typed query, per-occurrence match highlighting, match-count feedback ("N of M"), next/prev stepping and scroll-to-match are all self-contained in this widget \u2014 no other prop or host wiring is needed. Plain case-insensitive substring matching only, no regex, no cross-block spans. Unset (default) \u2192 zero behavior change.',B.l,null,!1)
B.hXA=new A.D("serifH1",B.a8,"Opt-in encyclopedia-style DISPLAY TITLE: renders a top-level `# ` Markdown heading in a serif font stack (Georgia / Times New Roman / Noto Serif / generic serif fallback \u2014 no new font asset bundled, so this always renders with whatever serif face the platform already has) instead of the body sans-serif, at a larger display size. Applies to every `# ` heading in the document (in practice just the one at the very top \u2014 see `document`) in BOTH the eager and `lazyBlocks` read-view paths. Off by default: zero behavior change for every existing caller.",B.l,null,!1)
B.hYl=new A.D("imagesTable",B.b4,"Enables `local:<id>` resolution for a standalone `![alt](src)` image block (and gives inline `![alt](src)` mid-paragraph a real target to resolve, though inline never promotes to a block): the id looks up a row in this table, whose imageSrcColumn holds a base64 payload rendered via the engine's existing local-bytes image path (same as `record`'s image preview) \u2014 never fetched. An http(s) src, or a `local:<id>` that doesn't resolve, always renders as alt text; this node has no image-fetch code at all. Unset (default) \u2192 zero behavior change.",B.l,null,!1)
B.hKk=new A.D("imageSrcColumn",B.L,'Column on imagesTable holding the base64 image payload (default "b64").',B.l,null,!1)
