B.hcU=new A.dp("record","An INLINE single-row editor for a master-detail RIGHT pane: renders the record editor for the injected `rowId` (from explorer/pages) in place of a modal sheet, so selecting an item shows its full editable detail in the pane instead of a popup. Autosaves when the app sets app.autosave; otherwise carries its own Save.",B.dzd,!1)
B.hEX=new A.D("appletId",B.Q,"Id of the applet to embed (passed to the host resolver).",B.l,null,!1)
B.hMM=new A.D("instanceId",B.Q,"Optional instance id, when one applet is embedded more than once.",B.l,null,!1)
B.i2V=new A.D("appletColumn",B.Q,"Row-bound: read the applet id from this COLUMN of the injected row (table/rowId injected by a master-detail host) instead of appletId.",B.l,null,!1)
B.hVL=new A.D("instanceFromRow",B.a8,"Row-bound: use the injected row id as the instance, so each row holds its OWN dataset (e.g. a comment item embeds its own wireframe).",B.l,null,!1)
B.hZ3=new A.D("screen",B.Q,"Which screen of the embedded applet to show; default = its first.",B.l,null,!1)
B.hIc=new A.D("bare",B.a8,"Render the child WITHOUT its own top-level chrome (a `header` or `backbutton` at the top of the embedded body) \u2014 for a host surface that already draws a header and would otherwise stack two. The resolver can ask for the same thing by returning an EmbeddedApplet with `chrome: false`; either side asking is enough. Default false = today's behavior, byte-identical.",B.l,null,!1)
B.i0Y=new A.D("scope",B.W,'Optional `{table, rowId}` to open the embedded applet ALREADY SCOPED to one row (e.g. `{"table":"boards","rowId":"..."}`) \u2014 reuses the child applet\'s OWN `scopeTargets` (the same explorer-driven scoping a user gets by picking that row), so the embed opens with no unscoped list flash. Absent = unscoped default screen (unchanged behavior).',B.l,null,!1)
B.hOy=new A.D("height",B.aS,"Slot height in px (default 520); set for taller/shorter embeds.",B.l,null,!1)
B.i2U=new A.D("width",B.aS,"Optional fixed width; omit to fill the available width.",B.l,null,!1)
B.hOl=new A.D("presetScope",B.W,"priorun-0802 unit2: `{table, column, value}` \u2014 directly calls BoardState.setScope(table, column, value) on the CHILD board so any scopeColumn-aware node inside it (e.g. bubl's `scopeColumn`) filters by that column, with no scopeTargets declaration needed. Distinct from `scope` above (opens on one specific row via the child's OWN declared scopeTargets). `value` supports the same live-token convention every filter-shaped prop uses ($rowId = this embed own injected row, $selected:<table> = the host board live selection, $playerId, or a literal). FAIL-CLOSED: a configured-but-unresolved token (nothing selected yet) sets the scope to a sentinel matching no real row \u2014 never falls back to unscoped \u2014 unless `scopeOptional: true` is also set. Absent = no setScope call at all (unchanged default).",B.l,null,!1)
B.hJb=new A.D("scopeOptional",B.a8,'Pairs with `presetScope` only. Default false keeps presetScope fail-closed (unresolved token -> sentinel, empty scoped set). Set true to instead CLEAR the scope on an unresolved token (full unscoped child) \u2014 for a user-driven selection-chip use where "nothing selected yet" should show everything, not nothing. Mirrors priolanes\' `scopeOptional`.',B.l,null,!1)
B.hQe=new A.D("embedSpecOverrides",B.W,"Opt-in: a map SHALLOW-merged onto the embedded applet's picked ROOT node spec at mount \u2014 EMBED side wins, only for the keys given here (a present key replaces that key on the root node wholesale, it does not deep-merge nested maps/lists; every other key on the root node is untouched). Lets one host surface ask an embedded applet's root to render slightly differently (e.g. a canvas embed opting into `{\"gestureModel\": \"panFirst\"}`) WITHOUT changing the embedded applet's own JSON, so every other mount of that same applet stays byte-identical. Absent = today's exact behavior (root passed through unchanged).",B.l,null,!1)
B.dyc=s([B.hEX,B.hMM,B.i2V,B.hVL,B.hZ3,B.hIc,B.i0Y,B.hOy,B.i2U,B.hOl,B.hJb,B.hQe],t.G)
