B.hdj=new A.dp("grouplist","One long list of rows in user-made groups. Rows drag by a handle within and between groups, groups drag by theirs; a drop writes only the group and order columns it changes. Each group has a color bar and a menu to rename, recolor or delete it (its rows stay). Sort (my order, last added, A to Z) and filter (status, groups, tags) are device settings. Rows with no group, or a group that is gone, always show at the end. Scrolls itself when given a bounded height (`fill: true` under a root `footer` layout).",B.d9b,!1)
B.hSs=new A.D("groups",B.W,"REQUIRED. { table, nameColumn?, colorColumn?, orderColumn? } (defaults name, color, order), as on grouplist.",B.l,null,!1)
B.i_A=new A.D("settingKey",B.Q,'Prefix of the device setting remembering a custom colour (as on grouplist; default "grouplist").',B.l,null,!1)
B.hQZ=new A.D("label",B.Q,'Chip text (default "New group"); may be a {lang: text} map.',B.l,null,!0)
B.di5=s([B.hSs,B.i_A,B.hQZ],t.G)
B.hcO=new A.dp("groupadd",'A "+ New group" chip that opens the group editor ("New group": name + colour) and adds the group. Made for a root footer\'s `above` slot, so it follows the bottom box in every view.',B.di5,!1)
