B.hdy=new A.dp("recordpage",'The page of one record of a record type (e.g. a Person): round initials avatar + full name, a label/value row per field ("add" when empty), YOUR FIELDS (fields the user added; type-wide, then this record\'s own), and "+ Add field". Esc / x / back ask "Save changes?" when edited; Cmd/Ctrl+S saves. Seeds the type on first open and splits old full names into the name parts.',B.d5k,!1)
B.hXq=new A.D("kinds",B.W,"List of record-kind specs (recordpage props) to seed and to hide plumbing columns for.",B.l,null,!1)
B.dpj=s([B.hXq],t.G)
B.hct=new A.dp("recordtypes",'Settings list of the record-type catalog: each type expands to its fields (drag handle to reorder, type label on the right, tap to rename or remove with a confirm, "+ Add field"); a muted "+ New type (later)" row.',B.dpj,!1)
B.hNY=new A.D("rowId",B.Q,"The row id, or `$selected:<table>`, as on record.",B.l,null,!1)
B.hQv=new A.D("titleColumn",B.L,'Title column (default "title").',B.l,null,!1)
B.hJU=new A.D("doneColumn",B.L,'Boolean done column for the title band checkbox (optional). njnest-1111: false \u2014 no done column at all: the subtasks have no ticks either ("N inside", plain "- " bullets when copied).',B.l,null,!1)
