B.dT0=new A.b(B.aF,["I have an idea and want it on my TradingView chart","\uc544\uc774\ub514\uc5b4\uac00 \uc788\uace0 TradingView \ucc28\ud2b8\uc5d0 \uc62c\ub9ac\uace0 \uc2f6\uc5b4\uc694","\u6211\u6709\u4e2a\u60f3\u6cd5\uff0c\u60f3\u653e\u5230\u6211\u7684 TradingView \u56fe\u8868\u4e0a","\u30a2\u30a4\u30c7\u30a2\u304c\u3042\u308b\u306e\u3067\u3001TradingView \u306e\u30c1\u30e3\u30fc\u30c8\u306b\u8f09\u305b\u305f\u3044","Tengo una idea y quiero verla en mi gr\xe1fico de TradingView","Ich habe eine Idee und will sie in meinem TradingView-Chart sehen","J'ai une id\xe9e et je veux la voir sur mon graphique TradingView"],t.w)
B.dS1=new A.b(B.aF,["You have an idea for when to buy and sell, and you want it on your chart.","\uc5b8\uc81c \uc0ac\uace0 \ud314\uc9c0\uc5d0 \ub300\ud55c \uc544\uc774\ub514\uc5b4\uac00 \uc788\uace0, \uadf8\uac83\uc744 \ucc28\ud2b8\uc5d0 \uc62c\ub9ac\uace0 \uc2f6\uc2b5\ub2c8\ub2e4.","\u4f60\u6709\u4e00\u4e2a\u5173\u4e8e\u4f55\u65f6\u4e70\u5165\u548c\u5356\u51fa\u7684\u60f3\u6cd5\uff0c\u60f3\u628a\u5b83\u653e\u5230\u56fe\u8868\u4e0a\u3002","\u3044\u3064\u8cb7\u3044\u3001\u3044\u3064\u58f2\u308b\u304b\u306e\u30a2\u30a4\u30c7\u30a2\u304c\u3042\u308a\u3001\u305d\u308c\u3092\u30c1\u30e3\u30fc\u30c8\u306b\u8f09\u305b\u305f\u3044\u3002","Tienes una idea de cu\xe1ndo comprar y vender, y quieres verla en tu gr\xe1fico.","Du hast eine Idee, wann du kaufen und verkaufen willst, und m\xf6chtest sie in deinem Chart sehen.","Vous avez une id\xe9e de quand acheter et vendre, et vous la voulez sur votre graphique."],t.w)
B.dTy=new A.b(B.aF,["Open Build and answer the first question: what to watch.","\uad6c\uc131\uc744 \uc5f4\uace0 \uccab \uc9c8\ubb38\uc5d0 \ub2f5\ud558\uc138\uc694: \ubb34\uc5c7\uc744 \uc9c0\ucf1c\ubcfc\uae4c\uc694.","\u6253\u5f00 Build\uff0c\u56de\u7b54\u7b2c\u4e00\u4e2a\u95ee\u9898\uff1a\u8981\u5173\u6ce8\u4ec0\u4e48\u3002","Build \u3092\u958b\u304d\u3001\u6700\u521d\u306e\u8cea\u554f\u306b\u7b54\u3048\u307e\u3059\uff1a\u4f55\u3092\u898b\u308b\u304b\u3002","Abre Build y responde la primera pregunta: qu\xe9 vigilar.","\xd6ffne Build und beantworte die erste Frage: was beobachtet werden soll.","Ouvrez Build et r\xe9pondez \xe0 la premi\xe8re question : quoi surveiller."],t.w)
B.dSY=new A.b(B.aF,["Answer the questions: when to buy and how careful. (Some builds also ask when to sell.)","\uc9c8\ubb38\uc5d0 \ub2f5\ud558\uc138\uc694: \uc5b8\uc81c \uc0b4\uc9c0, \uc5bc\ub9c8\ub098 \uc2e0\uc911\ud560\uc9c0. (\uc77c\ubd80 \uad6c\uc131\uc740 \uc5b8\uc81c \ud314\uc9c0\ub3c4 \ubb3b\uc2b5\ub2c8\ub2e4.)","\u56de\u7b54\u95ee\u9898\uff1a\u4f55\u65f6\u4e70\u5165\u4ee5\u53ca\u8981\u591a\u8c28\u614e\u3002\uff08\u6709\u4e9b\u6784\u5efa\u8fd8\u4f1a\u95ee\u4f55\u65f6\u5356\u51fa\u3002\uff09","\u8cea\u554f\u306b\u7b54\u3048\u307e\u3059\uff1a\u3044\u3064\u8cb7\u3046\u304b\u3001\u3069\u308c\u3060\u3051\u614e\u91cd\u306b\u3059\u308b\u304b\u3002\uff08\u30d3\u30eb\u30c9\u306b\u3088\u3063\u3066\u306f\u3001\u3044\u3064\u58f2\u308b\u304b\u3082\u805e\u304b\u308c\u307e\u3059\u3002\uff09","Responde las preguntas: cu\xe1ndo comprar y con cu\xe1nto cuidado. (Algunos dise\xf1os tambi\xe9n preguntan cu\xe1ndo vender.)","Beantworte die Fragen: wann gekauft wird und wie vorsichtig. (Manche Aufbauten fragen auch, wann verkauft wird.)","R\xe9pondez aux questions : quand acheter et avec quelle prudence. (Certaines constructions demandent aussi quand vendre.)"],t.w)
B.dQQ=new A.b(B.aF,[u.kx,"\ud14c\uc2a4\ud2b8\ub97c \uc5f4\uace0 \uacfc\uac70 \uac00\uaca9\uc5d0 \ub300\ud55c \ud310\uc815\uc744 \uc77d\uc5b4 \ubcf4\uc138\uc694.","\u6253\u5f00 Test\uff0c\u67e5\u770b\u5728\u8fc7\u53bb\u4ef7\u683c\u4e0a\u7684\u7ed3\u8bba\u3002","Test \u3092\u958b\u304d\u3001\u904e\u53bb\u306e\u4fa1\u683c\u3067\u306e\u5224\u5b9a\u3092\u8aad\u307f\u307e\u3059\u3002","Abre Test y lee el veredicto sobre precios pasados.",u.bN,u.eS],t.w)
B.dS2=new A.b(B.aF,["Open Run and tap Copy script, then paste it into TradingView's Pine editor.","\uc2e4\ud589\uc744 \uc5f4\uace0 \uc2a4\ud06c\ub9bd\ud2b8 \ubcf5\uc0ac\ub97c \ub204\ub978 \ub2e4\uc74c TradingView\uc758 Pine \ud3b8\uc9d1\uae30\uc5d0 \ubd99\uc5ec\ub123\uc73c\uc138\uc694.","\u6253\u5f00 Run\uff0c\u70b9\u201c\u590d\u5236\u811a\u672c\u201d\uff0c\u7136\u540e\u7c98\u8d34\u5230 TradingView \u7684 Pine \u7f16\u8f91\u5668\u3002","Run \u3092\u958b\u3044\u3066\u300c\u30b9\u30af\u30ea\u30d7\u30c8\u3092\u30b3\u30d4\u30fc\u300d\u3092\u30bf\u30c3\u30d7\u3057\u3001TradingView \u306e Pine \u30a8\u30c7\u30a3\u30bf\u306b\u8cbc\u308a\u4ed8\u3051\u307e\u3059\u3002","Abre Run, toca Copiar script y p\xe9galo en el editor Pine de TradingView.","\xd6ffne Run, tippe auf \u201eSkript kopieren\u201c und f\xfcge es in den Pine-Editor von TradingView ein.","Ouvrez Run, touchez Copier le script, puis collez dans l'\xe9diteur Pine de TradingView."],t.w)
B.dRb=new A.b(B.aF,["You now have a script you can paste into TradingView.","\uc774\uc81c TradingView\uc5d0 \ubd99\uc5ec\ub123\uc744 \uc218 \uc788\ub294 \uc2a4\ud06c\ub9bd\ud2b8\uac00 \uc0dd\uacbc\uc2b5\ub2c8\ub2e4.","\u73b0\u5728\u4f60\u6709\u4e86\u4e00\u4e2a\u53ef\u4ee5\u7c98\u8d34\u5230 TradingView \u7684\u811a\u672c\u3002","TradingView \u306b\u8cbc\u308a\u4ed8\u3051\u3089\u308c\u308b\u30b9\u30af\u30ea\u30d7\u30c8\u304c\u3067\u304d\u307e\u3057\u305f\u3002","Ya tienes un script que puedes pegar en TradingView.","Du hast jetzt ein Skript, das du in TradingView einf\xfcgen kannst.","Vous avez maintenant un script \xe0 coller dans TradingView."],t.w)
B.dQw=new A.b(B.aF,["I changed my script. Can I still trust it?","\uc2a4\ud06c\ub9bd\ud2b8\ub97c \ubc14\uafe8\uc5b4\uc694. \uadf8\ub798\ub3c4 \ubbff\uc5b4\ub3c4 \ub420\uae4c\uc694?","\u6211\u6539\u4e86\u811a\u672c\u3002\u8fd8\u80fd\u76f8\u4fe1\u5b83\u5417\uff1f","\u30b9\u30af\u30ea\u30d7\u30c8\u3092\u5909\u66f4\u3057\u307e\u3057\u305f\u3002\u307e\u3060\u4fe1\u983c\u3067\u304d\u307e\u3059\u304b\uff1f","Cambi\xe9 mi script. \xbfPuedo seguir confiando en \xe9l?","Ich habe mein Skript ge\xe4ndert. Kann ich ihm noch vertrauen?","J'ai modifi\xe9 mon script. Puis-je encore m'y fier ?"],t.w)
B.dQC=new A.b(B.aF,["You tested a script, then changed it, and you want to know if the test still applies.","\uc2a4\ud06c\ub9bd\ud2b8\ub97c \ud14c\uc2a4\ud2b8\ud55c \ub4a4 \ubc14\uafe8\uace0, \uadf8 \ud14c\uc2a4\ud2b8\uac00 \uc544\uc9c1 \uc720\ud6a8\ud55c\uc9c0 \uc54c\uace0 \uc2f6\uc2b5\ub2c8\ub2e4.","\u4f60\u6d4b\u8bd5\u4e86\u4e00\u4e2a\u811a\u672c\uff0c\u4e4b\u540e\u53c8\u6539\u4e86\u5b83\uff0c\u60f3\u77e5\u9053\u8fd9\u6b21\u6d4b\u8bd5\u662f\u5426\u4ecd\u7136\u9002\u7528\u3002","\u30b9\u30af\u30ea\u30d7\u30c8\u3092\u30c6\u30b9\u30c8\u3057\u305f\u3042\u3068\u5909\u66f4\u3057\u3001\u305d\u306e\u30c6\u30b9\u30c8\u304c\u307e\u3060\u5f53\u3066\u306f\u307e\u308b\u304b\u77e5\u308a\u305f\u3044\u3002","Probaste un script, luego lo cambiaste, y quieres saber si la prueba sigue valiendo.","Du hast ein Skript getestet, es dann ge\xe4ndert und willst wissen, ob der Test noch gilt.","Vous avez test\xe9 un script, puis l'avez modifi\xe9, et voulez savoir si le test vaut encore."],t.w)
B.dQO=new A.b(B.aF,["Open Run. If you changed your build since testing, a note says so.","\uc2e4\ud589\uc744 \uc5ec\uc138\uc694. \ud14c\uc2a4\ud2b8\ud55c \ub4a4 \uad6c\uc131\uc744 \ubc14\uafe8\ub2e4\uba74 \uc548\ub0b4\uac00 \uc54c\ub824 \uc90d\ub2c8\ub2e4.","\u6253\u5f00 Run\u3002\u5982\u679c\u6d4b\u8bd5\u540e\u4f60\u6539\u8fc7\u6784\u5efa\uff0c\u4f1a\u6709\u63d0\u793a\u8bf4\u660e\u3002","Run \u3092\u958b\u304d\u307e\u3059\u3002\u30c6\u30b9\u30c8\u5f8c\u306b\u30d3\u30eb\u30c9\u3092\u5909\u66f4\u3057\u3066\u3044\u308c\u3070\u3001\u305d\u306e\u65e8\u306e\u8868\u793a\u304c\u51fa\u307e\u3059\u3002","Abre Run. Si cambiaste tu dise\xf1o despu\xe9s de probarlo, una nota lo dice.","\xd6ffne Run. Wenn du deinen Aufbau seit dem Test ge\xe4ndert hast, weist ein Hinweis darauf hin.","Ouvrez Run. Si vous avez modifi\xe9 votre construction depuis le test, une note l'indique."],t.w)
B.dRQ=new A.b(B.aF,["Tap Test again.","\ub2e4\uc2dc \ud14c\uc2a4\ud2b8\ub97c \ub204\ub974\uc138\uc694.","\u70b9\u201c\u518d\u6d4b\u4e00\u6b21\u201d\u3002","\u300c\u3082\u3046\u4e00\u5ea6\u30c6\u30b9\u30c8\u300d\u3092\u30bf\u30c3\u30d7\u3057\u307e\u3059\u3002","Toca Probar de nuevo.","Tippe auf \u201eNochmal testen\u201c.","Touchez Tester \xe0 nouveau."],t.w)
B.dSy=new A.b(B.aF,["Read the new verdict.","\uc0c8 \ud310\uc815\uc744 \uc77d\uc5b4 \ubcf4\uc138\uc694.","\u67e5\u770b\u65b0\u7684\u7ed3\u8bba\u3002","\u65b0\u3057\u3044\u5224\u5b9a\u3092\u8aad\u307f\u307e\u3059\u3002","Lee el nuevo veredicto.","Lies das neue Urteil.","Lisez le nouveau verdict."],t.w)
B.dR1=new A.b(B.aF,["Go back to Run and copy.","\uc2e4\ud589\uc73c\ub85c \ub3cc\uc544\uac00 \ubcf5\uc0ac\ud558\uc138\uc694.","\u56de\u5230 Run \u5e76\u590d\u5236\u3002","Run \u306b\u623b\u3063\u3066\u30b3\u30d4\u30fc\u3057\u307e\u3059\u3002","Vuelve a Run y copia.","Geh zur\xfcck zu Run und kopiere.","Retournez \xe0 Run et copiez."],t.w)
B.dSu=new A.b(B.aF,["You now have a script whose test matches what you copy.","\uc774\uc81c \ubcf5\uc0ac\ud558\ub294 \uc2a4\ud06c\ub9bd\ud2b8\uc640 \ud14c\uc2a4\ud2b8 \ub0b4\uc6a9\uc774 \uc77c\uce58\ud569\ub2c8\ub2e4.","\u73b0\u5728\u4f60\u590d\u5236\u7684\u811a\u672c\u4e0e\u6d4b\u8bd5\u7684\u5185\u5bb9\u4e00\u81f4\u3002","\u30b3\u30d4\u30fc\u3059\u308b\u30b9\u30af\u30ea\u30d7\u30c8\u3068\u3001\u30c6\u30b9\u30c8\u3057\u305f\u5185\u5bb9\u304c\u4e00\u81f4\u3057\u307e\u3057\u305f\u3002","Ya tienes un script cuya prueba coincide con lo que copias.","Du hast jetzt ein Skript, dessen Test zu dem passt, was du kopierst.","Le test correspond maintenant au script que vous copiez."],t.w)
B.dRT=new A.b(B.aF,["What are the big funds holding?","\ud070 \ud380\ub4dc\ub294 \ubb34\uc5c7\uc744 \ubcf4\uc720\ud558\uace0 \uc788\ub098\uc694?","\u5927\u578b\u57fa\u91d1\u6301\u6709\u4ec0\u4e48\uff1f","\u5927\u304d\u306a\u30d5\u30a1\u30f3\u30c9\u306f\u4f55\u3092\u4fdd\u6709\u3057\u3066\u3044\u308b\uff1f","\xbfQu\xe9 tienen los grandes fondos?","Was halten die gro\xdfen Fonds?","Que d\xe9tiennent les grands fonds ?"],t.w)
B.dRJ=new A.b(B.aF,["You want to see what large funds report holding.","\ud070 \ud380\ub4dc\uac00 \ubcf4\uc720\ud588\ub2e4\uace0 \ubcf4\uace0\ud55c \uac83\uc744 \ubcf4\uace0 \uc2f6\uc2b5\ub2c8\ub2e4.","\u4f60\u60f3\u770b\u770b\u5927\u578b\u57fa\u91d1\u7533\u62a5\u6301\u6709\u4ec0\u4e48\u3002","\u5927\u304d\u306a\u30d5\u30a1\u30f3\u30c9\u304c\u5831\u544a\u3057\u305f\u4fdd\u6709\u5185\u5bb9\u3092\u898b\u305f\u3044\u3002","Quieres ver lo que los grandes fondos declaran tener.","Du willst sehen, was gro\xdfe Fonds als Bestand melden.","Vous voulez voir ce que les grands fonds d\xe9clarent d\xe9tenir."],t.w)
B.dTb=new A.b(B.aF,["Open Ideas, then Portfolios.","\uc544\uc774\ub514\uc5b4\ub97c \uc5f4\uace0 \ud3ec\ud2b8\ud3f4\ub9ac\uc624\ub85c \uac00\uc138\uc694.","\u6253\u5f00\u201c\u521b\u610f\u201d\uff0c\u518d\u8fdb\u5165\u201c\u6295\u8d44\u7ec4\u5408\u201d\u3002","\u300c\u30a2\u30a4\u30c7\u30a2\u300d\u3092\u958b\u304d\u3001\u300c\u30dd\u30fc\u30c8\u30d5\u30a9\u30ea\u30aa\u300d\u3078\u9032\u307f\u307e\u3059\u3002","Abre Ideas y luego Carteras.","\xd6ffne \u201eIdeen\u201c, dann \u201ePortfolios\u201c.","Ouvrez Id\xe9es, puis Portefeuilles."],t.w)
B.dRI=new A.b(B.aF,["Type a fund's name in the search box and tap Search.","\uac80\uc0c9\ucc3d\uc5d0 \ud380\ub4dc \uc774\ub984\uc744 \uc785\ub825\ud558\uace0 \uac80\uc0c9\uc744 \ub204\ub974\uc138\uc694.","\u5728\u641c\u7d22\u6846\u91cc\u8f93\u5165\u57fa\u91d1\u540d\u79f0\uff0c\u7136\u540e\u70b9\u201c\u641c\u7d22\u201d\u3002","\u691c\u7d22\u30dc\u30c3\u30af\u30b9\u306b\u30d5\u30a1\u30f3\u30c9\u540d\u3092\u5165\u529b\u3057\u3001\u300c\u691c\u7d22\u300d\u3092\u30bf\u30c3\u30d7\u3057\u307e\u3059\u3002","Escribe el nombre de un fondo en el cuadro de b\xfasqueda y toca Buscar.","Gib den Namen eines Fonds ins Suchfeld ein und tippe auf Suchen.","Saisissez le nom d'un fonds dans la zone de recherche et touchez Rechercher."],t.w)
B.dQz=new A.b(B.aF,["Read each filing date: these are quarter-end holdings, filed up to 45 days late, not the fund's trading.","\uac01 \uc81c\ucd9c\uc77c\uc744 \ud655\uc778\ud558\uc138\uc694: \ubd84\uae30 \ub9d0 \ubcf4\uc720 \ub0b4\uc5ed\uc774\uba70 \ucd5c\ub300 45\uc77c \ub2a6\uac8c \uc81c\ucd9c\ub418\uace0, \ud380\ub4dc\uc758 \ub9e4\ub9e4\uac00 \uc544\ub2d9\ub2c8\ub2e4.","\u770b\u6bcf\u6761\u7684\u7533\u62a5\u65e5\u671f\uff1a\u8fd9\u662f\u5b63\u5ea6\u672b\u7684\u6301\u4ed3\uff0c\u6700\u591a\u665a 45 \u5929\u7533\u62a5\uff0c\u5e76\u975e\u57fa\u91d1\u7684\u4ea4\u6613\u3002","\u5404\u63d0\u51fa\u65e5\u3092\u78ba\u8a8d\u3057\u307e\u3059\uff1a\u56db\u534a\u671f\u672b\u306e\u4fdd\u6709\u3067\u3001\u63d0\u51fa\u306f\u6700\u592745\u65e5\u9045\u308c\u3001\u30d5\u30a1\u30f3\u30c9\u306e\u58f2\u8cb7\u3067\u306f\u3042\u308a\u307e\u305b\u3093\u3002","Mira cada fecha de presentaci\xf3n: son posiciones de fin de trimestre, presentadas hasta 45 d\xedas tarde, no las operaciones del fondo.","Lies jedes Meldedatum: Es sind Best\xe4nde zum Quartalsende, bis zu 45 Tage versp\xe4tet gemeldet, nicht der Handel des Fonds.","Lisez chaque date de d\xe9p\xf4t : ce sont les positions de fin de trimestre, d\xe9pos\xe9es jusqu'\xe0 45 jours plus tard, pas les transactions du fonds."],t.w)
B.dQV=new A.b(B.aF,["You now know what the fund reported, and when.","\uc774\uc81c \ud380\ub4dc\uac00 \ubb34\uc5c7\uc744, \uc5b8\uc81c \ubcf4\uace0\ud588\ub294\uc9c0 \uc54c\uac8c \ub418\uc5c8\uc2b5\ub2c8\ub2e4.","\u73b0\u5728\u4f60\u77e5\u9053\u4e86\u57fa\u91d1\u7533\u62a5\u4e86\u4ec0\u4e48\uff0c\u4ee5\u53ca\u4f55\u65f6\u7533\u62a5\u3002","\u30d5\u30a1\u30f3\u30c9\u304c\u4f55\u3092\u3001\u3044\u3064\u5831\u544a\u3057\u305f\u304b\u304c\u5206\u304b\u308a\u307e\u3057\u305f\u3002","Ya sabes qu\xe9 declar\xf3 el fondo y cu\xe1ndo.","Du wei\xdft jetzt, was der Fonds gemeldet hat und wann.","Vous savez maintenant ce que le fonds a d\xe9clar\xe9, et quand."],t.w)
B.dT1=new A.b(B.aF,["I want many small edges working together","\uc5ec\ub7ec \uc791\uc740 \uc6b0\uc704\ub97c \ud568\uaed8 \uc4f0\uace0 \uc2f6\uc5b4\uc694","\u6211\u60f3\u8ba9\u591a\u4e2a\u5c0f\u4f18\u52bf\u4e00\u8d77\u53d1\u6325\u4f5c\u7528","\u5c0f\u3055\u306a\u512a\u4f4d\u6027\u3092\u3044\u304f\u3064\u304b\u7d44\u307f\u5408\u308f\u305b\u305f\u3044","Quiero que varias peque\xf1as ventajas trabajen juntas","Ich m\xf6chte viele kleine Vorteile zusammen nutzen","Je veux que plusieurs petits avantages travaillent ensemble"],t.w)
B.dRR=new A.b(B.aF,["You want several small signals in one build instead of one big idea.","\ud558\ub098\uc758 \ud070 \uc544\uc774\ub514\uc5b4 \ub300\uc2e0 \uc5ec\ub7ec \uc791\uc740 \uc2e0\ud638\ub97c \ud55c \ube4c\ub4dc\uc5d0 \ub2f4\uace0 \uc2f6\uc2b5\ub2c8\ub2e4.","\u4f60\u60f3\u5728\u4e00\u4e2a\u6784\u5efa\u91cc\u653e\u5165\u51e0\u4e2a\u5c0f\u4fe1\u53f7\uff0c\u800c\u4e0d\u662f\u4e00\u4e2a\u5927\u60f3\u6cd5\u3002","\u5927\u304d\u306a1\u3064\u306e\u30a2\u30a4\u30c7\u30a2\u3067\u306f\u306a\u304f\u3001\u5c0f\u3055\u306a\u30b7\u30b0\u30ca\u30eb\u3092\u3044\u304f\u3064\u304b1\u3064\u306e\u30d3\u30eb\u30c9\u306b\u5165\u308c\u305f\u3044\u3002","Quieres varias se\xf1ales peque\xf1as en un dise\xf1o en lugar de una gran idea.","Du willst mehrere kleine Signale in einem Aufbau statt einer gro\xdfen Idee.","Vous voulez plusieurs petits signaux dans une construction plut\xf4t qu'une grande id\xe9e."],t.w)
B.dSW=new A.b(B.aF,["Scroll to the bottom of Ideas and open Small edges.","\uc544\uc774\ub514\uc5b4 \ub9e8 \uc544\ub798\ub85c \uc2a4\ud06c\ub864\ud574 \uc791\uc740 \uc6b0\uc704\ub97c \uc5fd\ub2c8\ub2e4.","\u6eda\u52a8\u5230\u201c\u60f3\u6cd5\u201d\u9875\u9762\u5e95\u90e8\uff0c\u6253\u5f00\u5c0f\u4f18\u52bf\u3002","\u30a2\u30a4\u30c7\u30a2\u306e\u4e00\u756a\u4e0b\u307e\u3067\u30b9\u30af\u30ed\u30fc\u30eb\u3057\u3066\u300c\u5c0f\u3055\u306a\u512a\u4f4d\u6027\u300d\u3092\u958b\u304d\u307e\u3059\u3002","Baja hasta el final de Ideas y abre Peque\xf1as ventajas.","Scrolle ans Ende von Ideen und \xf6ffne Kleine Vorteile.","Faites d\xe9filer jusqu'au bas de Id\xe9es et ouvrez Petits avantages."],t.w)
B.dQx=new A.b(B.aF,["Add two blocks, for example RSI mean-rev and Volatility regime percentile.","\ube14\ub85d \ub450 \uac1c\ub97c \ucd94\uac00\ud569\ub2c8\ub2e4. \uc608\ub97c \ub4e4\uc5b4 RSI \ud3c9\uade0\ud68c\uadc0\uc640 Volatility regime percentile\uc785\ub2c8\ub2e4.","\u6dfb\u52a0\u4e24\u4e2a\u6a21\u5757\uff0c\u4f8b\u5982 RSI \u5747\u503c\u56de\u5f52\u548c Volatility regime percentile\u3002","\u30d6\u30ed\u30c3\u30af\u30922\u3064\u8ffd\u52a0\u3057\u307e\u3059\u3002\u305f\u3068\u3048\u3070 RSI\u5e73\u5747\u56de\u5e30 \u3068 Volatility regime percentile \u3067\u3059\u3002","A\xf1ade dos bloques, por ejemplo Reversi\xf3n RSI y Volatility regime percentile.","F\xfcge zwei Bausteine hinzu, zum Beispiel RSI-Umkehr und Volatility regime percentile.","Ajoutez deux blocs, par exemple RSI mean-rev et Volatility regime percentile."],t.w)
B.dRa=new A.b(B.aF,[u.kx,"\ud14c\uc2a4\ud2b8\ub97c \uc5f4\uc5b4 \uacfc\uac70 \uac00\uaca9\uc5d0 \ub300\ud55c \ud310\uc815\uc744 \uc77d\uc2b5\ub2c8\ub2e4.","\u6253\u5f00\u6d4b\u8bd5\uff0c\u67e5\u770b\u57fa\u4e8e\u5386\u53f2\u4ef7\u683c\u7684\u7ed3\u8bba\u3002","\u30c6\u30b9\u30c8\u3092\u958b\u304d\u3001\u904e\u53bb\u306e\u4fa1\u683c\u306b\u5bfe\u3059\u308b\u5224\u5b9a\u3092\u8aad\u307f\u307e\u3059\u3002","Abre Probar y lee el veredicto sobre precios pasados.",u.bN,u.eS],t.w)
B.dRS=new A.b(B.aF,["You now have several small signals tested together.","\uc774\uc81c \uc5ec\ub7ec \uc791\uc740 \uc2e0\ud638\ub97c \ud568\uaed8 \ud14c\uc2a4\ud2b8\ud588\uc2b5\ub2c8\ub2e4.","\u73b0\u5728\u4f60\u5df2\u7ecf\u628a\u51e0\u4e2a\u5c0f\u4fe1\u53f7\u653e\u5728\u4e00\u8d77\u6d4b\u8bd5\u8fc7\u4e86\u3002","\u3044\u304f\u3064\u304b\u306e\u5c0f\u3055\u306a\u30b7\u30b0\u30ca\u30eb\u3092\u307e\u3068\u3081\u3066\u30c6\u30b9\u30c8\u3067\u304d\u307e\u3057\u305f\u3002","Ya tienes varias se\xf1ales peque\xf1as probadas juntas.","Du hast jetzt mehrere kleine Signale gemeinsam getestet.","Vous avez maintenant plusieurs petits signaux test\xe9s ensemble."],t.w)
