B.dZj=new A.b(B.J,["hidden = kept in the data, marked hidden in the app definition.","\uc228\uae40 = \ub370\uc774\ud130\uc5d0 \ub0a8\uc544 \uc788\uace0, \uc571 \uc815\uc758\uc5d0\uc11c \uc228\uae40\uc73c\ub85c \ud45c\uc2dc\ub428.","\u9690\u85cf = \u4fdd\u7559\u5728\u6570\u636e\u4e2d\uff0c\u5728\u5e94\u7528\u5b9a\u4e49\u91cc\u6807\u8bb0\u4e3a\u9690\u85cf\u3002","\u091b\u093f\u092a\u093e = \u0921\u0947\u091f\u093e \u092e\u0947\u0902 \u092e\u094c\u091c\u0942\u0926, \u0910\u092a \u092a\u0930\u093f\u092d\u093e\u0937\u093e \u092e\u0947\u0902 \u091b\u093f\u092a\u093e \u091a\u093f\u0939\u094d\u0928\u093f\u0924\u0964","oculto = se guarda en los datos, marcado como oculto en la definici\xf3n de la app.","masqu\xe9 = conserv\xe9 dans les donn\xe9es, marqu\xe9 masqu\xe9 dans la d\xe9finition de l\u2019app.","\u0645\u062e\u0641\u064a = \u0645\u062d\u0641\u0648\u0638 \u0641\u064a \u0627\u0644\u0628\u064a\u0627\u0646\u0627\u062a\u060c \u0648\u0645\u0639\u0644\u064e\u0651\u0645 \u0643\u0645\u062e\u0641\u064a \u0641\u064a \u062a\u0639\u0631\u064a\u0641 \u0627\u0644\u062a\u0637\u0628\u064a\u0642.","oculto = guardado nos dados, marcado como oculto na defini\xe7\xe3o do app.","\u0441\u043a\u0440\u044b\u0442\u043e = \u0445\u0440\u0430\u043d\u0438\u0442\u0441\u044f \u0432 \u0434\u0430\u043d\u043d\u044b\u0445, \u043f\u043e\u043c\u0435\u0447\u0435\u043d\u043e \u0441\u043a\u0440\u044b\u0442\u044b\u043c \u0432 \u043e\u043f\u0438\u0441\u0430\u043d\u0438\u0438 \u043f\u0440\u0438\u043b\u043e\u0436\u0435\u043d\u0438\u044f.","verborgen = in den Daten gespeichert, in der App-Definition als verborgen markiert.","\u975e\u8868\u793a = \u30c7\u30fc\u30bf\u306b\u306f\u6b8b\u308a\u3001\u30a2\u30d7\u30ea\u5b9a\u7fa9\u3067\u975e\u8868\u793a\u3068\u6307\u5b9a\u3002","gizli = veride tutulur, uygulama tan\u0131m\u0131nda gizli olarak i\u015faretlidir.","\u1ea9n = v\u1eabn l\u01b0u trong d\u1eef li\u1ec7u, \u0111\u01b0\u1ee3c \u0111\xe1nh d\u1ea5u \u1ea9n trong \u0111\u1ecbnh ngh\u0129a \u1ee9ng d\u1ee5ng.","nascosto = conservato nei dati, segnato come nascosto nella definizione dell\u2019app.","\u067e\u0646\u0647\u0627\u0646 = \u062f\u0631 \u062f\u0627\u062f\u0647\u200c\u0647\u0627 \u0646\u06af\u0647 \u062f\u0627\u0634\u062a\u0647 \u0645\u06cc\u200c\u0634\u0648\u062f \u0648 \u062f\u0631 \u062a\u0639\u0631\u06cc\u0641 \u0628\u0631\u0646\u0627\u0645\u0647 \u067e\u0646\u0647\u0627\u0646 \u0639\u0644\u0627\u0645\u062a \u062e\u0648\u0631\u062f\u0647 \u0627\u0633\u062a.","ukryte = zapisane w danych, oznaczone jako ukryte w definicji aplikacji.","\u043f\u0440\u0438\u0445\u043e\u0432\u0430\u043d\u043e = \u0437\u0431\u0435\u0440\u0456\u0433\u0430\u0454\u0442\u044c\u0441\u044f \u0432 \u0434\u0430\u043d\u0438\u0445, \u043f\u043e\u0437\u043d\u0430\u0447\u0435\u043d\u043e \u043f\u0440\u0438\u0445\u043e\u0432\u0430\u043d\u0438\u043c \u0432 \u043e\u043f\u0438\u0441\u0456 \u0437\u0430\u0441\u0442\u043e\u0441\u0443\u043d\u043a\u0443.","verborgen = bewaard in de gegevens, als verborgen gemarkeerd in de app-definitie.","dold = sparas i datan, markerad som dold i appens definition.","skryt\xe9 = ulo\u017eeno v datech, v definici aplikace ozna\u010deno jako skryt\xe9.","\u03ba\u03c1\u03c5\u03c6\u03cc = \u03c5\u03c0\u03ac\u03c1\u03c7\u03b5\u03b9 \u03c3\u03c4\u03b1 \u03b4\u03b5\u03b4\u03bf\u03bc\u03ad\u03bd\u03b1, \u03c3\u03b7\u03bc\u03b5\u03b9\u03c9\u03bc\u03ad\u03bd\u03bf \u03c9\u03c2 \u03ba\u03c1\u03c5\u03c6\u03cc \u03c3\u03c4\u03bf\u03bd \u03bf\u03c1\u03b9\u03c3\u03bc\u03cc \u03c4\u03b7\u03c2 \u03b5\u03c6\u03b1\u03c1\u03bc\u03bf\u03b3\u03ae\u03c2."],t.w)
