B.fjx=new A.b(B.m,["Nothing starred yet \u2014 tap \u2606 on any item.","Nada destacado a\xfan \u2014 toca \u2606 en cualquier elemento.","Rien n'est encore marqu\xe9 \u2014 appuyez sur \u2606 sur un \xe9l\xe9ment.","Noch nichts markiert \u2014 tippe auf \u2606 bei einem Eintrag.","Ancora nulla in evidenza \u2014 tocca \u2606 su un elemento.","Nada marcado ainda \u2014 toque em \u2606 em qualquer item.","Nog niets favoriet \u2014 tik op \u2606 bij een item.","Inget favoritmarkerat \xe4n \u2014 tryck p\xe5 \u2606 p\xe5 valfritt objekt.","Zat\xedm nic nen\xed obl\xedben\xe9 \u2014 klepn\u011bte na \u2606 u polo\u017eky.","\u03a4\u03af\u03c0\u03bf\u03c4\u03b1 \u03b4\u03b5\u03bd \u03ad\u03c7\u03b5\u03b9 \u03b5\u03c0\u03b9\u03c3\u03b7\u03bc\u03b1\u03bd\u03b8\u03b5\u03af \u03b1\u03ba\u03cc\u03bc\u03b7 \u2014 \u03c0\u03b1\u03c4\u03ae\u03c3\u03c4\u03b5 \u2606 \u03c3\u03b5 \u03ad\u03bd\u03b1 \u03c3\u03c4\u03bf\u03b9\u03c7\u03b5\u03af\u03bf.","Nic jeszcze nie oznaczono \u2014 dotknij \u2606 przy dowolnym elemencie.","\u0429\u0435 \u043d\u0456\u0447\u043e\u0433\u043e \u043d\u0435 \u043e\u0431\u0440\u0430\u043d\u043e \u2014 \u0442\u043e\u0440\u043a\u043d\u0456\u0442\u044c\u0441\u044f \u2606 \u0431\u0456\u043b\u044f \u0435\u043b\u0435\u043c\u0435\u043d\u0442\u0430.","\u041f\u043e\u043a\u0430 \u043d\u0438\u0447\u0435\u0433\u043e \u043d\u0435 \u043e\u0442\u043c\u0435\u0447\u0435\u043d\u043e \u2014 \u043d\u0430\u0436\u043c\u0438\u0442\u0435 \u2606 \u043d\u0430 \u043b\u044e\u0431\u043e\u043c \u044d\u043b\u0435\u043c\u0435\u043d\u0442\u0435.","Hen\xfcz y\u0131ld\u0131zlanan yok \u2014 bir \xf6\u011fede \u2606 simgesine dokunun.","Ch\u01b0a c\xf3 m\u1ee5c n\xe0o \u0111\u01b0\u1ee3c \u0111\xe1nh d\u1ea5u sao \u2014 nh\u1ea5n \u2606 tr\xean m\u1ed9t m\u1ee5c.","\uc544\uc9c1 \uc990\uaca8\ucc3e\uae30\ud55c \ud56d\ubaa9\uc774 \uc5c6\uc2b5\ub2c8\ub2e4 \u2014 \ud56d\ubaa9\uc758 \u2606\ub97c \ud0ed\ud558\uc138\uc694.","\u307e\u3060\u30b9\u30bf\u30fc\u4ed8\u304d\u306e\u9805\u76ee\u306f\u3042\u308a\u307e\u305b\u3093 \u2014 \u9805\u76ee\u306e\u2606\u3092\u30bf\u30c3\u30d7\u3057\u3066\u304f\u3060\u3055\u3044\u3002","\u8fd8\u6ca1\u6709\u52a0\u661f\u6807\u7684\u9879\u76ee \u2014 \u70b9\u6309\u4efb\u610f\u9879\u76ee\u4e0a\u7684\u2606\u3002","\u0644\u0627 \u0634\u064a\u0621 \u0645\u0645\u064a\u0632 \u0628\u0639\u062f \u2014 \u0627\u0646\u0642\u0631 \u0639\u0644\u0649 \u2606 \u0639\u0644\u0649 \u0623\u064a \u0639\u0646\u0635\u0631.","\u0905\u092d\u0940 \u0924\u0915 \u0915\u0941\u091b \u092d\u0940 \u092a\u0938\u0902\u0926\u0940\u0926\u093e \u0928\u0939\u0940\u0902 \u0939\u0948 \u2014 \u0915\u093f\u0938\u0940 \u0906\u0907\u091f\u092e \u092a\u0930 \u2606 \u091f\u0948\u092a \u0915\u0930\u0947\u0902\u0964","\u0647\u0646\u0648\u0632 \u0686\u06cc\u0632\u06cc \u0633\u062a\u0627\u0631\u0647\u200c\u062f\u0627\u0631 \u0646\u0634\u062f\u0647 \u2014 \u0631\u0648\u06cc \u2606 \u0647\u0631 \u0645\u0648\u0631\u062f \u0636\u0631\u0628\u0647 \u0628\u0632\u0646\u06cc\u062f."],t.w)
