B.fxa=new A.b(B.m,["This step has no measures.","Este paso no tiene medidas.","Cette \xe9tape n\u2019a aucune mesure.","Dieser Schritt hat keine Kennzahlen.","Questo passaggio non ha misure.","Esta etapa n\xe3o tem medidas.","Deze stap heeft geen meetwaarden.","Steget har inga m\xe5tt.","Tento krok nem\xe1 \u017e\xe1dn\xe9 ukazatele.","\u0391\u03c5\u03c4\u03cc \u03c4\u03bf \u03b2\u03ae\u03bc\u03b1 \u03b4\u03b5\u03bd \u03ad\u03c7\u03b5\u03b9 \u03bc\u03b5\u03b3\u03ad\u03b8\u03b7.","Ten krok nie ma miar.","\u0426\u0435\u0439 \u043a\u0440\u043e\u043a \u043d\u0435 \u043c\u0430\u0454 \u043f\u043e\u043a\u0430\u0437\u043d\u0438\u043a\u0456\u0432.","\u0423 \u044d\u0442\u043e\u0433\u043e \u0448\u0430\u0433\u0430 \u043d\u0435\u0442 \u043f\u043e\u043a\u0430\u0437\u0430\u0442\u0435\u043b\u0435\u0439.","Bu ad\u0131m\u0131n \xf6l\xe7\xfcs\xfc yok.","B\u01b0\u1edbc n\xe0y kh\xf4ng c\xf3 s\u1ed1 \u0111o.","\uc774 \ub2e8\uacc4\uc5d0\ub294 \uce21\uc815\uac12\uc774 \uc5c6\uc2b5\ub2c8\ub2e4.","\u3053\u306e\u30b9\u30c6\u30c3\u30d7\u306b\u306f\u6307\u6a19\u304c\u3042\u308a\u307e\u305b\u3093\u3002","\u6b64\u6b65\u9aa4\u6ca1\u6709\u5ea6\u91cf\u3002","\u0644\u0627 \u0645\u0642\u0627\u064a\u064a\u0633 \u0644\u0647\u0630\u0647 \u0627\u0644\u062e\u0637\u0648\u0629.","\u0907\u0938 \u091a\u0930\u0923 \u092e\u0947\u0902 \u0915\u094b\u0908 \u092e\u093e\u092a \u0928\u0939\u0940\u0902 \u0939\u0948\u0964","\u0627\u06cc\u0646 \u0645\u0631\u062d\u0644\u0647 \u0633\u0646\u062c\u0647\u200c\u0627\u06cc \u0646\u062f\u0627\u0631\u062f."],t.w)
