B.h0s=new A.b(B.aB,["Each layer decides: on the chart, or a panel when one needs it.","\ub808\uc774\uc5b4\ub9c8\ub2e4 \uc815\ud574\uc694: \ucc28\ud2b8 \uc704, \ub610\ub294 \ud544\uc694\ud558\uba74 \ubcc4\ub3c4 \ud328\ub110.","Cada capa decide: sobre el gr\xe1fico, o un panel si lo necesita.","\u7531\u5404\u56fe\u5c42\u51b3\u5b9a:\u753b\u5728\u56fe\u8868\u4e0a,\u9700\u8981\u65f6\u53e6\u5f00\u9762\u677f\u3002","\u30ec\u30a4\u30e4\u30fc\u3054\u3068\u306b\u6c7a\u307e\u308a\u307e\u3059:\u30c1\u30e3\u30fc\u30c8\u4e0a\u3001\u5fc5\u8981\u306a\u3089\u5c02\u7528\u30d1\u30cd\u30eb\u3002","Jede Ebene entscheidet: im Chart oder in einem Panel, wenn n\xf6tig.","Elke laag beslist: op de grafiek, of een paneel als dat nodig is."],t.w)
