B.f9o=new A.b(B.m,[u.d,"Opcional. Apunta esta app a TU propio forge para previsualizar con precios reales (solo uso personal; nunca se comparte ni sincroniza). D\xe9jalo vac\xedo para usar datos de demostraci\xf3n.",u.d,"Optional. Lass diese App echte Kurse von DEINEM eigenen Forge laden (nur pers\xf6nliche Nutzung; wird nie geteilt oder synchronisiert). Leer lassen = Demodaten.",u.d,u.d,"Optioneel. Laat deze app echte koersen ophalen van JOUW eigen forge (alleen persoonlijk gebruik; nooit gedeeld of gesynchroniseerd). Leeg laten = demodata.",u.d,u.d,u.d,u.d,u.d,u.d,u.d,u.d,"\uc120\ud0dd \uc0ac\ud56d. \uc774 \uc571\uc774 \ub0b4 forge \uc11c\ubc84\uc5d0\uc11c \uc2e4\uc81c \uac00\uaca9\uc744 \ubd88\ub7ec\uc624\uac8c \ud569\ub2c8\ub2e4 (\uac1c\uc778 \uc6a9\ub3c4 \uc804\uc6a9, \uacf5\uc720\xb7\ub3d9\uae30\ud654\ub418\uc9c0 \uc54a\uc74c). \ube44\uc6cc \ub450\uba74 \ub370\ubaa8 \ub370\uc774\ud130\ub97c \uc0ac\uc6a9\ud569\ub2c8\ub2e4.","\u4efb\u610f\u3002\u3053\u306e\u30a2\u30d7\u30ea\u304c\u3042\u306a\u305f\u81ea\u8eab\u306e forge \u304b\u3089\u5b9f\u969b\u306e\u4fa1\u683c\u3092\u53d6\u5f97\u3057\u3066\u30d7\u30ec\u30d3\u30e5\u30fc\u3057\u307e\u3059(\u500b\u4eba\u5229\u7528\u306e\u307f\u3001\u5171\u6709\u30fb\u540c\u671f\u3055\u308c\u307e\u305b\u3093)\u3002\u7a7a\u6b04\u306a\u3089\u30c7\u30e2\u30c7\u30fc\u30bf\u306e\u307e\u307e\u3067\u3059\u3002","\u53ef\u9009\u3002\u8ba9\u6b64\u5e94\u7528\u4ece\u4f60\u81ea\u5df1\u7684 forge \u670d\u52a1\u5668\u83b7\u53d6\u771f\u5b9e\u4ef7\u683c\u7528\u4e8e\u9884\u89c8(\u4ec5\u9650\u4e2a\u4eba\u4f7f\u7528,\u4e0d\u5171\u4eab\u4e5f\u4e0d\u540c\u6b65)\u3002\u7559\u7a7a\u5219\u4f7f\u7528\u6f14\u793a\u6570\u636e\u3002",u.d,u.d,u.d],t.w)
