B.fwr=new A.b(B.m,["Remove seed?","\xbfQuitar semilla?","Retirer la graine ?","Startartikel entfernen?","Rimuovere il seme?","Remover semente?","Zaadartikel verwijderen?","Ta bort fr\xf6-artikel?","Odebrat v\xfdchoz\xed \u010dl\xe1nek?","\u0391\u03c6\u03b1\u03af\u03c1\u03b5\u03c3\u03b7 \u03ac\u03c1\u03b8\u03c1\u03bf\u03c5-\u03c3\u03c0\u03cc\u03c1\u03bf\u03c5;","Usun\u0105\u0107 ziarno?","\u041f\u0440\u0438\u0431\u0440\u0430\u0442\u0438 \u0434\u0436\u0435\u0440\u0435\u043b\u043e?","\u0423\u0431\u0440\u0430\u0442\u044c \u0438\u0441\u0445\u043e\u0434\u043d\u0443\u044e \u0441\u0442\u0430\u0442\u044c\u044e?","Tohum kald\u0131r\u0131ls\u0131n m\u0131?","B\u1ecf h\u1ea1t gi\u1ed1ng?","\uc2dc\ub4dc\ub97c \ud574\uc81c\ud560\uae4c\uc694?","\u30b7\u30fc\u30c9\u3092\u89e3\u9664\u3057\u307e\u3059\u304b\uff1f","\u8981\u79fb\u9664\u79cd\u5b50\u5417\uff1f","\u0625\u0632\u0627\u0644\u0629 \u0627\u0644\u0628\u0630\u0631\u0629\u061f","\u0938\u0940\u0921 \u0939\u091f\u093e\u090f\u0902?","\u0628\u0630\u0631 \u062d\u0630\u0641 \u0634\u0648\u062f\u061f"],t.w)
B.fpV=new A.b(B.m,["The article stays saved; its linked layer is released unless other seeds need it.","El art\xedculo permanece guardado; su capa vinculada se libera salvo que otras semillas la necesiten.","L'article reste enregistr\xe9 ; sa couche li\xe9e est lib\xe9r\xe9e sauf si d'autres graines en ont besoin.","Der Artikel bleibt gespeichert; seine verkn\xfcpfte Ebene wird freigegeben, sofern kein anderer Startartikel sie noch braucht.","L'articolo resta salvato; il suo livello collegato viene rilasciato a meno che altri semi non ne abbiano bisogno.","O artigo permanece salvo; sua camada vinculada \xe9 liberada, a menos que outras sementes precisem dela.","Het artikel blijft opgeslagen; de gekoppelde laag wordt vrijgegeven tenzij andere zaadartikelen die nodig hebben.","Artikeln f\xf6rblir sparad; dess l\xe4nkade lager frig\xf6rs om inte andra fr\xf6-artiklar beh\xf6ver det.","\u010cl\xe1nek z\u016fstane ulo\u017een; jeho propojen\xe1 vrstva se uvoln\xed, pokud ji nepot\u0159ebuje jin\xfd v\xfdchoz\xed \u010dl\xe1nek.","\u03a4\u03bf \u03ac\u03c1\u03b8\u03c1\u03bf \u03c0\u03b1\u03c1\u03b1\u03bc\u03ad\u03bd\u03b5\u03b9 \u03b1\u03c0\u03bf\u03b8\u03b7\u03ba\u03b5\u03c5\u03bc\u03ad\u03bd\u03bf\xb7 \u03c4\u03bf \u03c3\u03c5\u03bd\u03b4\u03b5\u03b4\u03b5\u03bc\u03ad\u03bd\u03bf \u03b5\u03c0\u03af\u03c0\u03b5\u03b4\u03cc \u03c4\u03bf\u03c5 \u03b1\u03c0\u03b5\u03bb\u03b5\u03c5\u03b8\u03b5\u03c1\u03ce\u03bd\u03b5\u03c4\u03b1\u03b9 \u03b5\u03ba\u03c4\u03cc\u03c2 \u03b1\u03bd \u03c4\u03bf \u03c7\u03c1\u03b5\u03b9\u03ac\u03b6\u03bf\u03bd\u03c4\u03b1\u03b9 \u03ac\u03bb\u03bb\u03b1 \u03ac\u03c1\u03b8\u03c1\u03b1-\u03c3\u03c0\u03cc\u03c1\u03bf\u03b9.","Artyku\u0142 pozostaje zapisany; jego powi\u0105zana warstwa zostanie zwolniona, chyba \u017ce potrzebuj\u0105 jej inne ziarna.","\u0421\u0442\u0430\u0442\u0442\u044f \u0437\u0430\u043b\u0438\u0448\u0430\u0454\u0442\u044c\u0441\u044f \u0437\u0431\u0435\u0440\u0435\u0436\u0435\u043d\u043e\u044e; \u0457\u0457 \u043f\u043e\u0432\u2019\u044f\u0437\u0430\u043d\u0438\u0439 \u0448\u0430\u0440 \u0431\u0443\u0434\u0435 \u0437\u0432\u0456\u043b\u044c\u043d\u0435\u043d\u043e, \u044f\u043a\u0449\u043e \u0432\u0456\u043d \u043d\u0435 \u043f\u043e\u0442\u0440\u0456\u0431\u0435\u043d \u0456\u043d\u0448\u0438\u043c \u0434\u0436\u0435\u0440\u0435\u043b\u0430\u043c.","\u0421\u0442\u0430\u0442\u044c\u044f \u043e\u0441\u0442\u0430\u0451\u0442\u0441\u044f \u0441\u043e\u0445\u0440\u0430\u043d\u0451\u043d\u043d\u043e\u0439; \u0441\u0432\u044f\u0437\u0430\u043d\u043d\u044b\u0439 \u0441 \u043d\u0435\u0439 \u0441\u043b\u043e\u0439 \u043e\u0441\u0432\u043e\u0431\u043e\u0436\u0434\u0430\u0435\u0442\u0441\u044f, \u0435\u0441\u043b\u0438 \u043e\u043d \u043d\u0435 \u043d\u0443\u0436\u0435\u043d \u0434\u0440\u0443\u0433\u0438\u043c \u0438\u0441\u0445\u043e\u0434\u043d\u044b\u043c \u0441\u0442\u0430\u0442\u044c\u044f\u043c.","Makale kay\u0131tl\u0131 kal\u0131r; ba\u011flant\u0131l\u0131 katman\u0131, ba\u015fka tohumlar ihtiya\xe7 duymad\u0131\u011f\u0131 s\xfcrece serbest b\u0131rak\u0131l\u0131r.","B\xe0i vi\u1ebft v\u1eabn \u0111\u01b0\u1ee3c l\u01b0u; l\u1edbp li\xean k\u1ebft c\u1ee7a n\xf3 s\u1ebd \u0111\u01b0\u1ee3c gi\u1ea3i ph\xf3ng tr\u1eeb khi h\u1ea1t gi\u1ed1ng kh\xe1c c\u1ea7n \u0111\u1ebfn.","\ubb38\uc11c\ub294 \uacc4\uc18d \uc800\uc7a5\ub41c \uc0c1\ud0dc\ub85c \uc720\uc9c0\ub429\ub2c8\ub2e4. \uc5f0\uacb0\ub41c \ub808\uc774\uc5b4\ub294 \ub2e4\ub978 \uc2dc\ub4dc\uac00 \ud544\uc694\ub85c \ud558\uc9c0 \uc54a\ub294 \ud55c \ud574\uc81c\ub429\ub2c8\ub2e4.","\u8a18\u4e8b\u306f\u4fdd\u5b58\u3055\u308c\u305f\u307e\u307e\u3067\u3059\u3002\u30ea\u30f3\u30af\u3055\u308c\u305f\u30ec\u30a4\u30e4\u30fc\u306f\u3001\u4ed6\u306e\u30b7\u30fc\u30c9\u304c\u5fc5\u8981\u3068\u3057\u306a\u3044\u9650\u308a\u89e3\u653e\u3055\u308c\u307e\u3059\u3002","\u6587\u7ae0\u4ecd\u4f1a\u4fdd\u7559\u4fdd\u5b58\uff1b\u5176\u5173\u8054\u7684\u5c42\u4f1a\u88ab\u91ca\u653e\uff0c\u9664\u975e\u5176\u4ed6\u79cd\u5b50\u4ecd\u9700\u8981\u5b83\u3002","\u062a\u0628\u0642\u0649 \u0627\u0644\u0645\u0642\u0627\u0644\u0629 \u0645\u062d\u0641\u0648\u0638\u0629\u061b \u0648\u064a\u062a\u0645 \u062a\u062d\u0631\u064a\u0631 \u0637\u0628\u0642\u062a\u0647\u0627 \u0627\u0644\u0645\u0631\u062a\u0628\u0637\u0629 \u0645\u0627 \u0644\u0645 \u062a\u0643\u0646 \u0628\u0630\u0648\u0631 \u0623\u062e\u0631\u0649 \u0628\u062d\u0627\u062c\u0629 \u0625\u0644\u064a\u0647\u0627.","\u0932\u0947\u0916 \u0938\u0939\u0947\u091c\u093e \u0939\u0941\u0906 \u0930\u0939\u0947\u0917\u093e; \u0907\u0938\u0915\u0940 \u091c\u0941\u0921\u093c\u0940 \u0939\u0941\u0908 \u092a\u0930\u0924 \u0924\u092c \u0924\u0915 \u0939\u091f\u093e \u0926\u0940 \u091c\u093e\u090f\u0917\u0940 \u091c\u092c \u0924\u0915 \u0915\u093f\u0938\u0940 \u0905\u0928\u094d\u092f \u0938\u0940\u0921 \u0915\u094b \u0909\u0938\u0915\u0940 \u0906\u0935\u0936\u094d\u092f\u0915\u0924\u093e \u0928 \u0939\u094b\u0964","\u0645\u0642\u0627\u0644\u0647 \u0630\u062e\u06cc\u0631\u0647\u200c\u0634\u062f\u0647 \u0628\u0627\u0642\u06cc \u0645\u06cc\u200c\u0645\u0627\u0646\u062f\u061b \u0644\u0627\u06cc\u0647\u0654 \u067e\u06cc\u0648\u0646\u062f\u06cc \u0622\u0646 \u0622\u0632\u0627\u062f \u0645\u06cc\u200c\u0634\u0648\u062f \u0645\u06af\u0631 \u0627\u06cc\u0646\u06a9\u0647 \u0628\u0630\u0631\u0647\u0627\u06cc \u062f\u06cc\u06af\u0631 \u0628\u0647 \u0622\u0646 \u0646\u06cc\u0627\u0632 \u062f\u0627\u0634\u062a\u0647 \u0628\u0627\u0634\u0646\u062f."],t.w)
